const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let messageTimer,messageOutTimer;const toastKind=s=>/could not|error|unavailable|limit|invalid|failed|required|please|not /i.test(s)?'error':/removed|cleared|cancel/i.test(s)?'removed':/added|saved|submitted|placed|quantity|updated|confirmed|success|welcome|signed in/i.test(s)?'success':'info';
const toastIcons={success:'<path d="m5 12 5 5 9-10"/>',removed:'<path d="M5 12h14"/>',error:'<path d="M12 7v6m0 4h.01"/>',info:'<path d="M12 11v6m0-10h.01"/>'};
const message=s=>{const el=document.querySelector('#message');if(!el)return;clearTimeout(messageTimer);clearTimeout(messageOutTimer);el.classList.remove('toast-out','toast-show');el.textContent='';if(!s)return;const kind=toastKind(s);el.dataset.kind=kind;const ic=document.createElement('span');ic.className='toast-icon';ic.setAttribute('aria-hidden','true');ic.innerHTML='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">'+toastIcons[kind]+'</svg>';const tx=document.createElement('span');tx.className='toast-text';tx.textContent=s;const bar=document.createElement('i');bar.className='toast-bar';el.append(ic,tx,bar);void el.offsetWidth;el.classList.add('toast-show');messageTimer=setTimeout(()=>{el.classList.add('toast-out');messageOutTimer=setTimeout(()=>{el.textContent='';el.classList.remove('toast-show','toast-out');},350);},4000);};
// Mirror of the shop on the server (server/shop.mjs), refreshed after every api() call.
let state={products:[],orders:[],promotions:[],reviews:[],returns:[],repairs:[],customers:{},customCategories:[]};
state.promotions??=[];
let categories=['Laptop','Charger','Camera','Headphone','Speaker','Microphone','Other'];
const categoryLabels={Laptop:'Laptops',Charger:'Chargers',Camera:'Cameras',Headphone:'Headphones',Speaker:'Speakers',Microphone:'Microphones',Other:'Other'};
const icons=productIcons;
// Guest cart/wishlist stays in this browser; a signed-in user's own record is saved on the server.
const GUEST_KEY='devcomputer-guest-v1';
try{const g=JSON.parse(localStorage.getItem(GUEST_KEY)||'null');if(g)state.customers.guest=g;}catch{}
let pushTimer=null;
const save=()=>{
 try{if(state.customers?.guest)localStorage.setItem(GUEST_KEY,JSON.stringify(state.customers.guest));else localStorage.removeItem(GUEST_KEY);}catch{}
 if(!user)return;clearTimeout(pushTimer);
 pushTimer=setTimeout(()=>{pushTimer=null;shopCall('/me','PUT',state.customers[customerKey()]||{}).catch(e=>message('Could not save your changes: '+e.message));},400);
};
async function shopCall(path,method='GET',body){
 const token=storedCustomer()?.token;let r;
 try{r=await fetch(API+'/api/shop'+path,{method,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:method==='GET'||method==='DELETE'?undefined:JSON.stringify(body??{})});}
 catch{throw Error('Cannot reach the shop server. Check your connection and try again.');}
 const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Request failed ('+r.status+')');return data;
}
async function refreshState(){
 const guest=state.customers?.guest,key=user?customerKey():null,mine=pushTimer&&key?state.customers[key]:null;
 const next=await shopCall('/state');
 if(guest)next.customers.guest=guest;if(mine)next.customers[key]=mine;
 state=next;
}


function customerKey(){return user?.email.toLowerCase()||'guest';}
function savedData(){state.customers??={};return state.customers[customerKey()]??=( {wishlist:[],later:[],cart:{}} );}
function restoreCart(){cart={...savedData().cart};}
function saveCart(){savedData().cart={...cart};save();navigation();}
function mergeGuest(){const guest=state.customers?.guest;if(!guest||!user)return;const target=savedData();target.wishlist=[...new Set([...target.wishlist,...guest.wishlist])];target.later=[...new Set([...target.later,...guest.later])];for(const [id,q] of Object.entries(guest.cart)){const p=state.products.find(p=>p.id===+id&&p.active);if(p)target.cart[id]=Math.min(p.stock,(target.cart[id]||0)+q);}delete state.customers.guest;save();}
function toggleWish(id){const data=savedData(),has=data.wishlist.includes(+id);data.wishlist=has?data.wishlist.filter(x=>x!==+id):[...data.wishlist,+id];save();track(has?'wishlist_remove':'wishlist_add',user,{product:state.products.find(p=>p.id===+id)?.name||String(id)});navigation();return !has;}
function addItem(id){const p=state.products.find(p=>p.id===+id&&p.active);if(!p||p.stock<1)throw Error('This item is currently unavailable.');if((cart[id]||0)>=p.stock)throw Error('Stock limit reached');cart[id]=(cart[id]||0)+1;saveCart();track('add_to_cart',user,{product:p.name,product_id:p.id});message(p.name+' added to cart');cartFeedback(+id);}
function productArt(p){return p.image_url||({Laptop:'/assets/laptop.svg',Headphone:'/assets/headphones.svg'})[p.category]||'';}
function itemThumb(i){const p=state.products.find(x=>x.id===i.product_id)||{name:i.name,category:'',image_url:i.image_url||''};return `<span class="order-thumb">${itemVisual(p)}</span>`;}
function itemVisual(p){return productArt(p)?`<img src="${esc(productArt(p))}" alt="${esc(p.name)}">`:`<span aria-hidden="true">${icons[p.category]||icon('box')}</span>`;}

state.reviews??=[];state.returns??=[];
function returnLabel(item){return item.returnable?`Returnable within ${item.return_days||7} days of delivery`:'Not returnable';}
function ratingSummary(id){const r=(state.reviews||[]).filter(r=>r.product_id===+id);return r.length?`${(r.reduce((n,r)=>n+r.rating,0)/r.length).toFixed(1)} / 5 (${r.length} ${r.length===1?'review':'reviews'})`:'No reviews yet';}
function canReturn(order,item){return order.status==='Delivered'&&item.returnable&&order.delivered_at&&Date.now()/1000<=order.delivered_at+(item.return_days||7)*86400;}
async function api(path,method='GET',body){
if(typeof reloadLocal==='function')reloadLocal();
if(path==='/auth/me'){const c=await checkSession();user=c?{email:c.email,name:c.name,phone:c.phone,role:c.role||'customer'}:null;await refreshState();return user;}
if(path==='/auth/request-otp'){sessionStorage.setItem('demoEmail',body.email);return {message:'Demo code: 123456. No email is sent in this preview.'};}
if(path==='/auth/verify-otp'){if(body.code!=='123456')throw Error('Use the demo OTP: 123456');const u={email:body.email,role:body.email.toLowerCase()==='owner@demo.com'?'admin':body.email.toLowerCase()==='delivery@demo.com'?'delivery':'customer'};sessionStorage.setItem('demoUser',JSON.stringify(u));return u;}
if(path==='/auth/logout'){track('logout',user);await signOut();sessionStorage.removeItem('demoUser');user=null;await refreshState();return {};}
const result=await shopCall(path,method,body);await refreshState();return result;
}
function action(fn){return async e=>{e?.preventDefault();const button=e?.submitter||e?.currentTarget;if(button?.tagName==='BUTTON')button.disabled=true;try{await fn(e);}catch(err){message(err.message);}finally{if(button?.tagName==='BUTTON')button.disabled=false;}};}
// ---- Orders badge and new-order notifications ----
const SEEN_KEY='devcomputer-seen-orders';
function seenOrders(){try{return JSON.parse(localStorage.getItem(SEEN_KEY)||'null');}catch{return null;}}
function markOrdersSeen(){if(user?.role!=='customer')return;const m={};for(const o of state.orders||[])m[o.id]=o.status;try{localStorage.setItem(SEEN_KEY,JSON.stringify(m));}catch{}}
/** Owner: orders awaiting confirmation. Delivery: pending requests. Customer: orders with an unseen update. */
function ordersBadge(){
 if(!user)return 0;const list=state.orders||[];
 if(user.role==='admin')return list.filter(o=>o.status==='Placed').length;
 if(user.role==='delivery')return list.filter(o=>o.delivery_request?.status==='Pending').length;
 let seen=seenOrders();if(!seen){markOrdersSeen();seen=seenOrders()||{};}
 return list.filter(o=>seen[o.id]!==o.status).length;
}
function notifyOrders(text){
 message(text);
 try{if('Notification' in window&&Notification.permission==='granted')new Notification('Dev Computer',{body:text,icon:'/assets/laptop.svg',tag:'orders'});}catch{}
}
setInterval(async()=>{
 if(!user||document.hidden)return;
 const before=ordersBadge();
 try{await refreshState();}catch{return;}
 const after=ordersBadge();
 if(after>before)notifyOrders(user.role==='admin'?`New order received · ${after} awaiting confirmation`:user.role==='delivery'?'New delivery request':'Your order has an update');
 if(after!==before)navigation();
},20000);
function navigation(){
 const selectedNav=nav.querySelector('[aria-current="page"]')?.id||'navShop';
 const isAdmin=adminPath&&user?.role==='admin',isDelivery=deliveryPath&&user?.role==='delivery',qty=Object.values(cart).reduce((a,b)=>a+b,0);
 document.querySelector('#headerOffers').style.display=deliveryPath?'none':''; // no shop offers in the delivery portal
 if(deliveryPath&&!isDelivery){
  // Not signed in as a delivery partner: only a sign-in / sign-out action, no shop menu.
  nav.innerHTML=user?'<button id="logout" class="secondary">Sign out</button>':'<button id="login" class="secondary">Sign in</button>';
  nav.querySelectorAll('button').forEach(b=>{b.innerHTML=icon('user')+'<span>'+esc(b.textContent)+'</span>';});
  if(user)document.querySelector('#logout').onclick=action(async()=>{await api('/auth/logout','POST');user=null;navigation();login();});
  else document.querySelector('#login').onclick=()=>login();
  return;
 }
 nav.innerHTML=isDelivery?'<button id="orders" class="secondary">Requests & deliveries</button><button id="navProfile" class="secondary">My profile</button><button id="logout" class="secondary">Sign out</button>':isAdmin?`<button id="navShop" class="secondary">Products</button><button id="orders" class="secondary">Orders</button><button id="navStock" class="secondary">Stock</button><button id="navActivity" class="secondary">Activity</button><button id="logout" class="secondary">Re-enter portal</button>`:`<button id="navShop" class="secondary">Shop</button><button id="navWishlist" class="secondary">Wishlist (${savedData().wishlist.length})</button><button id="navCart" class="secondary">Cart (${qty})</button><button id="orders" class="secondary">My Orders</button><button id="navProfile" class="secondary">Profile</button>${user?'<button id="logout" class="secondary">Re-enter portal</button>':'<button id="login">Log in</button>'}`;
 if(!isDelivery){nav.insertAdjacentHTML('beforeend',`<button id="navOffers" class="secondary">${isAdmin?'Manage offers':'Offers & events'}</button>`);document.querySelector('#navOffers').onclick=()=>offersView();}
 if(!isDelivery){const repairButton=document.createElement('button');repairButton.id='navRepairs';repairButton.className='secondary';repairButton.textContent=isAdmin?'Repair Centre':'Repairs';if(isAdmin)nav.append(repairButton);else nav.querySelector('#navProfile').before(repairButton);repairButton.onclick=repairCentre;}
 if(document.querySelector('#navShop'))document.querySelector('#navShop').onclick=action(shop);
 if(document.querySelector('#navProfile'))document.querySelector('#navProfile').onclick=()=>profileView();
 document.querySelector('#orders').onclick=action(async()=>{profileOrderContext=false;if(!user){message('Log in to see your orders.');login('orders');return;}if('Notification' in window&&Notification.permission==='default'&&user.role!=='customer')Notification.requestPermission().catch(()=>{});await orders();markOrdersSeen();navigation();selectNav('orders');});
 if(isAdmin){document.querySelector('#navStock').onclick=stockView;document.querySelector('#navActivity').onclick=action(async()=>{selectNav('navActivity');await adminPanel(view);});}
 else if(!isDelivery){document.querySelector('#navWishlist').onclick=()=>{collectionReturnTo=null;collectionView('wishlist');};document.querySelector('#navCart').onclick=action(async()=>{products=await api('/products');cartView();});}
 const navIcons={navShop:'shop',navWishlist:'heart',navCart:'bag',orders:'box',navProfile:'user',navStock:'box',navOffers:'gift',navRepairs:'repair',navActivity:'user',logout:'user'};nav.querySelectorAll('button').forEach(b=>{const text=b.textContent.replace('My Orders','Orders');b.innerHTML=icon(navIcons[b.id]||'shop')+'<span>'+esc(text)+'</span>';});
 {const n=ordersBadge(),btn=nav.querySelector('#orders');if(n&&btn){btn.classList.add('has-badge');btn.insertAdjacentHTML('beforeend',`<span class="nav-badge" aria-label="${n} new">${n>9?'9+':n}</span>`);}}
 document.querySelector('#headerOffers').onclick=()=>offersView();
 if(user)document.querySelector('#logout').onclick=action(async()=>{await api('/auth/logout','POST');user=null;restoreCart();navigation();await shop();});
 else document.querySelector('#login').onclick=()=>login();
 selectNav(selectedNav);
}

function login(destination='shop'){
 customerSignIn(destination);return;
 user={email:deliveryPath?'delivery@demo.com':adminPath?'owner@demo.com':'customer@demo.com',role:deliveryPath?'delivery':adminPath?'admin':'customer'};
 restoreCart();navigation();
 if(destination==='profile')profileView();else if(destination==='orders'||deliveryPath)orders();else if(destination==='checkout')checkoutForm();else shop();
}

async function shop(restore={}){
 reloadLocal();refreshCategories();
 selectNav('navShop');
 if(deliveryPath){if(!user){login();return;}if(user.role!=='delivery'){view.innerHTML=`<div class="card"><h2>Delivery partner access required</h2><p>You are signed in as ${esc(user.email)}, which is not a delivery partner account. Delivery partners are set with DELIVERY_EMAILS on the server.</p><button id="switchToDelivery">Sign in as delivery partner</button></div>`;document.querySelector('#switchToDelivery').onclick=action(async()=>{await api('/auth/logout','POST');user=null;navigation();login();});return;}await orders();return;}
 products=await api('/products');
 if(adminPath){if(!user){login();return;}if(user.role!=='admin'){view.innerHTML='<div class="card"><h2>Owner access required</h2><p>Sign in with an owner email. Owners are set with OWNER_EMAILS on the server.</p><button id="switchToOwner">Sign in as owner</button></div>';document.querySelector('#switchToOwner').onclick=action(async()=>{await api('/auth/logout','POST');restoreCart();navigation();login();});return;}}
 view.innerHTML=`<div class="shop-search"><span>${icon('search')}</span><input id="search" placeholder="Search your next upgrade" aria-label="Search electronics"><button id="filterToggle" class="icon-button" aria-label="Show product filters" aria-expanded="${adminPath?'true':'false'}">${icon('filter')}</button></div>${promotionBanner()}<div class="section-bar"><h2>${adminPath?'Manage your shop':'Shop by category'}</h2><button class="subtle-link" id="allCategories">View all ${icon('arrow')}</button></div><div class="category-tabs" role="group" aria-label="Product categories"><button data-category="" class="selected"><span class="category-icon">${icon('box')}</span><span>All items</span></button>${categories.filter(c=>c!=='Other').map(c=>`<button data-category="${esc(c)}" class="secondary"><span class="category-icon">${categoryIcon(c)}</span><span>${esc(categoryLabels[c])}</span></button>`).join('')}</div><div id="advancedFilters" ${adminPath?'':'hidden'}><div class="card filters"><label>Company / Brand<select id="brand"><option value="">All companies</option>${[...new Set(products.map(p=>p.brand||'Other'))].sort().map(b=>`<option value="${esc(b)}">${esc(b)}</option>`).join('')}</select></label><label>Min price (₹)<input id="minPrice" type="number" min="0" placeholder="0"></label><label>Max price (₹)<input id="maxPrice" type="number" min="0" placeholder="Any price"></label><label>Sort by<select id="sort"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select></label><button id="clearFilters" class="secondary">Clear filters</button></div></div><div class="section-bar"><h2>${adminPath?'Your inventory':'The curated edit'}</h2>${adminPath?'<button id="newProduct">'+icon('plus')+' Add product</button>':'<button id="viewAllProducts" class="subtle-link">View all '+icon('arrow')+'</button>'}</div><div class="catalog-meta"><span id="resultCount" class="muted" role="status"></span>${adminPath?'':'<button id="cart" class="subtle-link">View cart '+icon('bag')+'</button>'}</div><div id="catalog"></div><div class="store-promise">${icon('shield')} <span>Thoughtfully chosen tech. Personal service.</span></div>`;
 document.querySelector('#filterToggle').onclick=()=>{const panel=document.querySelector('#advancedFilters');panel.hidden=!panel.hidden;document.querySelector('#filterToggle').setAttribute('aria-expanded',String(!panel.hidden));};
 if(adminPath){document.querySelector('#allCategories').insertAdjacentHTML('beforebegin','<button id="manageCategories" class="secondary">Manage categories</button>');document.querySelector('#manageCategories').onclick=categoryManager;}
 document.querySelector('#allCategories').onclick=()=>document.querySelector('[data-category=""]').click();
 const offersButton=document.querySelector('#bannerOffers');if(offersButton)offersButton.onclick=()=>{if(!adminPath&&!state.promotions.some(p=>p.featured&&promotionStatus(p)==='Active')){document.querySelector('[data-category="Headphone"]').click();setTimeout(()=>{const g=document.querySelector('#view .grid');const t=g?.previousElementSibling?.closest?.('.section-bar')||[...document.querySelectorAll('#view .section-bar')].pop()||g;if(t)scrollTo({top:t.getBoundingClientRect().top+scrollY-24,behavior:'smooth'});},60);}else offersView();};
 const resultHeader=document.querySelector('#catalog').previousElementSibling.previousElementSibling,metadata=document.querySelector('.catalog-meta'),catalog=document.querySelector('#catalog');
 const results=document.createElement('section'),resultsAnchor=document.createComment('catalog position');results.id='searchResults';resultHeader.before(resultsAnchor);resultHeader.before(results);results.append(resultHeader,metadata,catalog);document.querySelector('#allCategories').parentElement.classList.add('category-section-title');
 let category=restore.category||'',showAll=!!restore.showAll;
 if(document.querySelector('#viewAllProducts'))document.querySelector('#viewAllProducts').onclick=()=>{const btn=document.querySelector('#viewAllProducts');if(category){category='';showAll=true;document.querySelectorAll('[data-category]').forEach(x=>{const on=x.dataset.category==='';x.classList.toggle('selected',on);x.classList.toggle('secondary',!on);x.setAttribute('aria-pressed',String(on));});}else showAll=!showAll;btn.innerHTML=(showAll?'Show curated edit':'View all')+' '+icon('arrow');draw();const g=document.querySelector('#view .grid');if(g)scrollTo({top:g.getBoundingClientRect().top+scrollY-140,behavior:'smooth'});message(showAll?'Showing all products':'Showing the curated edit');};
 if(adminPath)document.querySelector('#newProduct').onclick=()=>productForm();else document.querySelector('#cart').onclick=cartView;
 const draw=()=>{
 const q=document.querySelector('#search').value.trim().toLowerCase(),brand=document.querySelector('#brand').value,min=document.querySelector('#minPrice').value,max=document.querySelector('#maxPrice').value,sort=document.querySelector('#sort').value;
 const searching=!!q;view.classList.toggle('searching',searching);resultHeader.querySelector('h2').textContent=searching?'Search results':adminPath?'Your inventory':'The curated edit';if(searching)document.querySelector('.shop-search').after(results);else resultsAnchor.after(results);
 const invalid=min!==''&&max!==''&&+min>+max;
 const filtered=products.filter(p=>(!category||q||p.category===category)&&(!brand||p.brand===brand)&&[p.name,p.brand,p.category,p.description].some(value=>String(value||'').toLowerCase().includes(q))&&(min===''||p.price_paise>=+min*100)&&(max===''||p.price_paise<=+max*100));
 if(sort!=='featured')filtered.sort((a,b)=>sort==='low'?a.price_paise-b.price_paise:b.price_paise-a.price_paise);
 document.querySelector('#resultCount').textContent=invalid?'Minimum price must be less than maximum price.':`${filtered.length} product${filtered.length===1?'':'s'} found`;
 const card=p=>`<article class="card product-card"><div class="product-image"><button class="product-image-link" data-product="${p.id}" aria-label="View ${esc(p.name)} details">${itemVisual(p)}</button><small class="product-tag">${p.stock?'IN STOCK':'SOLD OUT'}</small>${!adminPath?`<button class="wish-button icon-button" data-wish="${p.id}" aria-label="${savedData().wishlist.includes(p.id)?'Remove from':'Add to'} wishlist: ${esc(p.name)}" aria-pressed="${savedData().wishlist.includes(p.id)}">${icon('heart',{filled:savedData().wishlist.includes(p.id)})}</button>`:''}</div><div class="product-copy"><h3><button class="product-name-link" data-product="${p.id}">${esc(p.name)}</button></h3><p class="product-spec">${esc(p.brand||categoryLabels[p.category])} · ${esc(p.description)}</p><div class="product-price-row"><p class="price">${priceTag(p,money)}</p>${!adminPath?`<div class="qty-stepper" data-stepper="${p.id}">${stepperHtml(p)}</div>`:''}</div><details class="product-more"><summary>Details & reviews</summary><p class="muted description">${esc(p.description)}</p><p class="muted">${p.stock} available</p>${p.specifications?`<dl class="product-specifications">${Object.entries(p.specifications).map(([key,value])=>`<div><dt>${esc(key==='SuitableFor'?'Best for':key)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`:''}${p.sample_listing?'<p class="notice">Sample listing: price and stock are for the demo. Owner can edit them. Product photos are manufacturer reference images.</p>':''}<p class="policy-tag ${p.returnable?'return-yes':''}">${returnLabel(p)}</p><button class="review-link" data-view-reviews="${p.id}">${ratingSummary(p.id)} · View reviews</button></details>${adminPath?`<div class="row"><button data-edit="${p.id}">Edit</button><button class="danger" data-delete="${p.id}">Remove</button></div>`:''}</div></article>`;
 const curated=[...filtered].sort((a,b)=>{const rank=p=>p.id===2?0:p.id===1?1:2;return rank(a)-rank(b);});
 const visible=adminPath||q||showAll||category||sort!=='featured'?filtered:curated.slice(0,8);
 document.querySelector('#catalog').innerHTML=invalid?'<div class="card">Adjust your price range to see products.</div>':!visible.length?'<div class="card"><h3>No matching products</h3><p>Try another company, category, or price range.</p></div>':`<div class="grid">${visible.map(card).join('')}</div>`;
 document.querySelectorAll('[data-product]').forEach(b=>b.onclick=action(()=>{const snapshot={category,showAll,scrollY:window.scrollY};for(const key of ['search','brand','minPrice','maxPrice','sort'])snapshot[key]=document.getElementById(key).value;return productDetails(+b.dataset.product,()=>shop(snapshot));}));
 document.querySelectorAll('[data-view-reviews]').forEach(b=>b.onclick=action(()=>reviewsView(+b.dataset.viewReviews)));
 bindSteppers();
 document.querySelectorAll('[data-wish]').forEach(b=>b.onclick=action(()=>{const added=toggleWish(b.dataset.wish);message(added?'Added to your wishlist':'Removed from your wishlist');draw();}));
 document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>productForm(products.find(x=>x.id===+b.dataset.edit)));
 document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=action(async()=>{if(confirm('Remove this product from the shop?')){await api('/admin/products/'+b.dataset.delete,'DELETE');await shop();}}));
 };
 document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('selected',x===b);x.classList.toggle('secondary',x!==b);x.setAttribute('aria-pressed',String(x===b));});draw();});
 ['search','minPrice','maxPrice'].forEach(id=>document.getElementById(id).oninput=draw);
 ['brand','sort'].forEach(id=>document.getElementById(id).onchange=draw);
 document.querySelector('#clearFilters').onclick=()=>{['search','minPrice','maxPrice','brand'].forEach(id=>document.getElementById(id).value='');document.getElementById('sort').value='featured';document.querySelector('[data-category=""]').click();};for(const key of ['search','brand','minPrice','maxPrice','sort'])if(restore[key]!==undefined)document.getElementById(key).value=restore[key];document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('selected',b.dataset.category===category);b.setAttribute('aria-pressed',String(b.dataset.category===category));});draw();if(restore.scrollY!==undefined)requestAnimationFrame(()=>window.scrollTo(0,restore.scrollY));
}
async function compressPhoto(file){
 if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPG, PNG, or WebP image.');
 if(file.size>5*1024*1024)throw Error('Choose an image smaller than 5 MB.');
 const url=URL.createObjectURL(file);
 try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('This photo could not be opened.'));img.src=url;});const scale=Math.min(1,1000/img.width,1000/img.height),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',0.78);}finally{URL.revokeObjectURL(url);}
}
function wirePriceFields(){
 const mrp=document.querySelector('#mrpInput'),pct=document.querySelector('#discountInput'),price=document.querySelector('#priceInput'),out=document.querySelector('#pricePreview');
 const paise=el=>el.value===''?null:Math.round(Number(el.value)*100);
 const show=()=>{const p={price_paise:paise(price),mrp_paise:paise(mrp)};const bad=p.mrp_paise&&p.price_paise&&p.mrp_paise<p.price_paise;out.classList.toggle('error',!!bad);out.innerHTML=bad?'Selling price is higher than the original price.':p.price_paise?'Customers will see: '+priceTag(p,money):'';};
 pct.oninput=()=>{const v=priceFromDiscount(paise(mrp),pct.value);if(v!=null&&pct.value!=='')price.value=v/100;show();};
 const fromPrice=()=>{const d=discountPercent({price_paise:paise(price),mrp_paise:paise(mrp)});pct.value=d||'';show();};
 price.oninput=fromPrice;mrp.oninput=()=>{if(pct.value&&paise(mrp)){pct.oninput();}else fromPrice();};show();
}
function productForm(p={}){
 refreshCategories();
 editing=p.id;let photo=p.image_url||'',reading=false;
 view.innerHTML=`<div class="card"><h2>${p.id?'Edit':'Add'} product</h2><form id="productForm"><label>Product name<input name="name" maxlength="150" required value="${esc(p.name)}"></label><div class="form-row"><label>Category<select name="category">${categories.map(c=>`<option value="${esc(c)}" ${c===p.category?'selected':''}>${esc(categoryLabels[c])}</option>`).join('')}</select></label><label>Company / Brand<input name="brand" maxlength="80" required placeholder="e.g. Dell, Sony, JBL" value="${esc(p.brand)}"></label></div><label>Description<textarea name="description" maxlength="4000">${esc(p.description)}</textarea></label><fieldset class="price-fields"><legend>Price &amp; offer</legend><div class="form-row price-row"><label>Original price / MRP (₹) <span class="muted">optional</span><input name="mrp" id="mrpInput" type="number" min="0" max="1000000" step="0.01" placeholder="e.g. 59999" value="${p.mrp_paise?p.mrp_paise/100:''}"></label><label>Offer discount (%)<input name="discount" id="discountInput" type="number" min="0" max="99" step="1" placeholder="0" value="${discountPercent(p)||''}"></label><label>Selling price (₹)<input name="price" id="priceInput" type="number" min="0.01" max="1000000" step="0.01" required value="${p.price_paise?p.price_paise/100:''}"></label></div><p class="price-preview" id="pricePreview" aria-live="polite"></p><small>Enter the original price and either the discount % or the selling price; the other one is calculated. Leave the original price empty for no offer.</small></fieldset><div class="form-row"><label>Stock<input name="stock" type="number" min="0" max="100000" required value="${p.stock??0}"></label></div><fieldset class="details-fields"><legend>Product details shown to customers</legend><label>Key features <span class="muted">one per line</span><textarea name="features" rows="5" maxlength="3000" placeholder="Active noise cancellation&#10;40-hour battery life&#10;Foldable design">${esc(featuresToText(p.features))}</textarea></label><label>Specifications <span class="muted">one per line as Name: value</span><textarea name="specifications" rows="6" maxlength="6000" placeholder="Battery: 40 hours&#10;Connectivity: Bluetooth 5.3&#10;Weight: 250 g">${esc(specsToText(p.specifications))}</textarea></label><div class="form-row"><label>Warranty<input name="warranty" maxlength="200" placeholder="e.g. 1 year manufacturer warranty" value="${esc(p.warranty)}"></label><label>What's in the box<input name="in_the_box" maxlength="300" placeholder="e.g. Headphones, USB-C cable, carry pouch" value="${esc(p.in_the_box)}"></label></div></fieldset><fieldset><legend>Return policy</legend><label>Can customers return this item?<select name="returnable" id="returnable"><option value="no" ${!p.returnable?'selected':''}>No — not returnable</option><option value="yes" ${p.returnable?'selected':''}>Yes — returnable after delivery</option></select></label><label id="returnDaysField">Return window (days after delivery)<input name="return_days" type="number" min="1" max="30" value="${p.return_days||7}"></label><small>The policy is shown before ordering and saved with the order.</small></fieldset><label>Upload product photo<input id="photoFile" type="file" accept="image/jpeg,image/png,image/webp"></label><small>JPG, PNG, or WebP · up to 5 MB. Photos in this demo are saved only in this browser.</small><div id="photoPreview" class="photo-preview"></div><button id="removePhoto" type="button" class="secondary">Remove photo</button><label style="margin-top:16px">Or paste an HTTPS image URL<input id="imageUrl" type="url" placeholder="https://…" value="${photo.startsWith('https://')?esc(photo):''}"></label><p id="photoStatus" role="status" class="muted"></p><div class="row"><button id="saveProduct">Save product</button><button id="back" type="button" class="secondary">Back</button></div></form></div>`;
 const preview=()=>{document.querySelector('#photoPreview').innerHTML=photo?`<img src="${esc(photo)}" alt="Product photo preview">`:'<span>No photo selected</span>';document.querySelector('#removePhoto').hidden=!photo;};preview();
 wirePriceFields();
 const toggleReturnDays=()=>{const enabled=document.querySelector('#returnable').value==='yes';document.querySelector('#returnDaysField').hidden=!enabled;document.querySelector('[name="return_days"]').disabled=!enabled;};document.querySelector('#returnable').onchange=toggleReturnDays;toggleReturnDays();
 document.querySelector('#photoFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;reading=true;document.querySelector('#saveProduct').disabled=true;try{photo=await compressPhoto(file);document.querySelector('#imageUrl').value='';preview();document.querySelector('#photoStatus').textContent='Photo ready. Click Save product to keep it.';}catch(err){document.querySelector('#photoStatus').textContent=err.message;e.target.value='';}finally{reading=false;document.querySelector('#saveProduct').disabled=false;}};
 document.querySelector('#imageUrl').onchange=e=>{const url=e.target.value.trim();if(url&&!url.startsWith('https://')){document.querySelector('#photoStatus').textContent='Image URLs must start with https://';return;}photo=url;document.querySelector('#photoFile').value='';preview();};
 document.querySelector('#removePhoto').onclick=()=>{photo='';document.querySelector('#photoFile').value='';document.querySelector('#imageUrl').value='';preview();};
 document.querySelector('#back').onclick=action(shop);
 document.querySelector('#productForm').onsubmit=action(async e=>{if(reading)throw Error('Please wait for the photo to finish.');const f=Object.fromEntries(new FormData(e.target));if(!f.name.trim()||!f.brand.trim())throw Error('Enter a product name and company.');await api('/admin/products'+(editing?'/'+editing:''),editing?'PUT':'POST',{name:f.name.trim(),brand:f.brand.trim(),category:f.category,description:f.description,price_paise:Math.round(Number(f.price)*100),mrp_paise:f.mrp?Math.round(Number(f.mrp)*100):null,stock:Number(f.stock),returnable:f.returnable==='yes',return_days:f.returnable==='yes'?Number(f.return_days):0,image_url:photo,...productDetailFields(f)});message('Product saved with its photo and company');await shop();});
}

function cartView(){
 selectNav('navCart');
 products=state.products.filter(p=>p.active);
 const items=Object.entries(cart).filter(([id,qty])=>qty>0&&products.some(p=>p.id===+id));
 const unavailable=Object.keys(cart).filter(id=>cart[id]>0&&!products.some(p=>p.id===+id));
 const subtotal=items.reduce((sum,[id,qty])=>sum+products.find(p=>p.id===+id).price_paise*qty,0),delivery=subtotal&&subtotal<100000?4900:0;
 view.innerHTML=`<h2>Your cart</h2><p class="muted">Buy now, or save items for another day.</p><div class="cart-layout"><div>${items.map(([id,qty])=>{const p=products.find(p=>p.id===+id);return `<article class="card basket-item"><div class="mini-image">${itemVisual(p)}</div><div><small>${esc(p.brand)}</small><h3><button class="product-name-link" data-saved-product="${p.id}">${esc(p.name)}</button></h3><p>${priceTag(p,money)} each · ${p.stock} in stock</p><p class="policy-tag">${returnLabel(p)}</p><div class="row"><button class="secondary" data-less="${id}" aria-label="Decrease quantity of ${esc(p.name)}">−</button><span>${qty}</span><button class="secondary" data-more="${id}" aria-label="Increase quantity of ${esc(p.name)}">+</button><button class="secondary" data-later="${id}">Save for later</button><button class="text-button" data-remove="${id}">Remove</button></div></div><strong>${money(p.price_paise*qty)}</strong></article>`;}).join('')||'<div class="card"><h3>Your cart is empty</h3><p>Browse your shop or move a saved item to the cart.</p></div>'}${unavailable.length?'<p class="muted">Unavailable products have been removed from your cart.</p>':''}</div><aside class="card order-summary"><h3>Order summary</h3><p class="summary-line"><span>Subtotal</span><strong>${money(subtotal)}</strong></p><p class="summary-line"><span>Delivery</span><strong>${money(delivery)}</strong></p><hr><p class="summary-line"><span>Total</span><strong>${money(subtotal+delivery)}</strong></p><p class="muted">Cash on delivery · Free delivery from ₹1,000</p>${items.length?'<button id="checkout">Proceed to checkout</button>':''}<button id="back" class="secondary">Continue shopping</button></aside></div><div class="row"><h3>Saved for later (${savedData().later.length})</h3><button id="viewLater" class="secondary">View saved items</button></div>`;
 unavailable.forEach(id=>delete cart[id]);if(unavailable.length)saveCart();
 document.querySelector('#back').onclick=action(shop);document.querySelector('#viewLater').onclick=()=>collectionView('later');
 document.querySelectorAll('[data-less]').forEach(b=>b.onclick=action(()=>{const id=b.dataset.less;if(--cart[id]<=0)delete cart[id];saveCart();cartView();}));
 document.querySelectorAll('[data-more]').forEach(b=>b.onclick=action(()=>{addItem(b.dataset.more);cartView();}));
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=action(()=>{delete cart[b.dataset.remove];saveCart();cartView();}));
 document.querySelectorAll('[data-later]').forEach(b=>b.onclick=action(()=>{const id=+b.dataset.later;const data=savedData();if(!data.later.includes(id))data.later.push(id);delete cart[id];saveCart();cartView();message('Item moved to Saved for later. It is not included in your total.');}));
 if(items.length)document.querySelector('#checkout').onclick=()=>{if(!user){login('checkout');message('Log in to complete your order. Your cart is saved.');return;}checkoutForm();};
}
