async function orders(){
 selectNav('orders');
 if(!user){login('orders');return;}
 const isAdmin=adminPath&&user.role==='admin',isDriver=deliveryPath&&user.role==='delivery',manager=isAdmin||isDriver;
 const list=await api(isAdmin?'/admin/orders':isDriver?'/delivery/orders':'/orders');
 const active=list.filter(o=>!['Delivered','Cancelled'].includes(o.status));
 view.innerHTML=`<h2>${isDriver?'Delivery requests & jobs':isAdmin?'Manage orders & delivery':'My orders'}</h2><p class="muted">${isDriver?'Only deliveries the shop has assigned to you appear here.':isAdmin?'Confirm new orders first. After confirmation, assign a delivery partner and manage dispatch.':'Track purchases, delivery updates, and payment status.'}</p><div class="metric-grid"><div class="card"><small>Total orders</small><strong>${list.length}</strong></div><div class="card"><small>In progress</small><strong>${active.length}</strong></div><div class="card"><small>Delivered</small><strong>${list.filter(o=>o.status==='Delivered').length}</strong></div></div><div class="card order-filters"><label>Find an order<input id="orderSearch" placeholder="Order ID, product${manager?', or customer':''}"></label><label>Status<select id="orderStatus"><option value="">All orders</option>${['Placed','Confirmed','Shipped','Out for delivery','Delivery failed','Delivered','Cancelled'].map(s=>`<option value="${s}">${s==='Placed'?'Awaiting owner confirmation':s}</option>`).join('')}</select></label><button id="back" class="secondary">${isDriver?'Refresh deliveries':'Back to shop'}</button></div><div id="orderList"></div>`;
 let deliveryFilter='all';if(isDriver){document.querySelector('#orderList').insertAdjacentHTML('beforebegin',`<div class="category-tabs"><button id="incomingRequests" class="secondary">Incoming requests (${list.filter(o=>o.status==='Confirmed'&&o.delivery_request?.status==='Pending').length})</button><button id="acceptedJobs" class="secondary">Accepted deliveries</button><button id="allDeliveries" class="secondary">All requests & history</button></div>`);}
 const draw=()=>{const q=document.querySelector('#orderSearch').value.toLowerCase(),status=document.querySelector('#orderStatus').value,filtered=list.filter(o=>(!isDriver||deliveryFilter==='all'||deliveryFilter==='requests'&&o.status==='Confirmed'&&o.delivery_request?.status==='Pending'||deliveryFilter==='accepted'&&o.delivery_request?.status==='Accepted'&&!['Delivered','Cancelled'].includes(o.status))&&(!status||o.status===status)&&[o.id,...o.items.map(i=>i.name),...(manager?[o.name,o.email,o.phone]:[])].some(x=>String(x).toLowerCase().includes(q)));
 document.querySelector('#orderList').innerHTML=filtered.map(o=>{
 const subtotal=o.items.reduce((sum,i)=>sum+i.price_paise*i.quantity,0),steps=['Placed','Confirmed','Shipped','Out for delivery','Delivered'],index=o.status==='Delivery failed'?3:steps.indexOf(o.status);
 const explanations={Placed:'Waiting for the owner to accept your order. Packing and delivery will start only after confirmation.',Confirmed:'The shop is preparing your order.',Shipped:'Your package has been dispatched.','Out for delivery':'The delivery partner is on the way.','Delivery failed':'The delivery attempt was unsuccessful. See the latest update below.',Delivered:'Your order has been marked delivered.',Cancelled:'This order was cancelled. Stock was restored.'};
 return `<article class="card order-card"><div class="row order-heading"><div><small>${esc(new Date(o.created*1000).toLocaleString())}</small><h3>${esc(o.id)}</h3></div><span class="status-pill status-${o.status.toLowerCase().replaceAll(' ','-')}">${o.status==='Placed'?'Awaiting owner confirmation':esc(o.status)}</span><strong>${money(o.total_paise)}</strong></div>${o.status==='Cancelled'?'<p class="cancelled-note">Order cancelled</p>':`<ol class="order-progress" aria-label="Order progress">${steps.map((step,i)=>`<li class="${i<=index?'complete':''}" ${i===index?'aria-current="step"':''}><span>${i<index?icon('check'):i+1}</span>${step}</li>`).join('')}</ol>`}<p class="muted">${explanations[o.status]}</p><p class="payment-status"><strong>Payment:</strong> ${esc(o.payment_method||'COD')}${o.payment_channel?' ('+esc(o.payment_channel)+')':''} · ${esc(o.payment_status||'Pay on delivery')}${o.payment_reference?`<br><small>Demo reference: ${esc(o.payment_reference)}</small>`:''}</p>${o.status==='Cancelled'&&o.payment_method==='Online demo'?'<p class="notice">Demo cancellation only. No real payment or refund has occurred.</p>':''}${!isDriver&&user?.role==='customer'&&o.assigned_name&&o.delivery_request?.status==='Accepted'?`<p class="delivery-partner-line">${icon('user')} Delivery partner: <strong>${esc(o.assigned_name)}</strong></p>`:''}<div class="order-items">${o.items.map(i=>`<div class="summary-line order-item-line"><span class="order-item-name">${itemThumb(i)}<span>${esc(i.name)}</span> <small>× ${i.quantity}</small></span><strong>${money(i.price_paise*i.quantity)}</strong></div>`).join('')}</div>${!isDriver&&o.status==='Delivered'?`<div class="receipt-actions"><button class="secondary" data-receipt="${esc(o.id)}">View / download receipt</button></div>`:''}${deliveryRequestMarkup(o,isAdmin,isDriver)}${afterSalesMarkup(o,isAdmin,isDriver)}<details><summary>Delivery details & updates</summary><div class="order-details"><h4>Deliver to</h4><p>${esc(o.name)} · ${esc(o.phone)}</p><p>${esc(o.address)}</p>${manager?`<p>${esc(o.email)}</p>`:''}<p><strong>Courier:</strong> ${esc(o.courier||'Not assigned yet')}</p><p><strong>Tracking reference:</strong> ${esc(o.tracking||'Not available yet')}</p>${o.eta?`<p><strong>Estimated delivery:</strong> ${esc(o.eta)}</p>`:''}<h4>Delivery history</h4><ul class="delivery-history">${(o.history||[{status:o.status,note:'Current order status',at:o.created,actor:'Shop'}]).slice().reverse().map(h=>`<li><strong>${esc(h.status)}</strong> <small>${esc(new Date(h.at*1000).toLocaleString())} · ${esc(h.actor)}</small><p>${esc(h.note)}</p></li>`).join('')}</ul><hr><p class="summary-line"><span>Items subtotal</span><strong>${money(subtotal)}</strong></p><p class="summary-line"><span>Delivery fee</span><strong>${money(o.total_paise-subtotal)}</strong></p><p class="summary-line"><span>Total</span><strong>${money(o.total_paise)}</strong></p></div></details>${isAdmin&&o.status==='Placed'?`<div class="confirmation-box"><strong>New order · Your approval is required</strong><p>Review the products and delivery address. Delivery is locked until you confirm.</p><div class="row"><button data-confirm-order="${esc(o.id)}">Confirm order</button><button class="danger" data-reject-order="${esc(o.id)}">Reject order</button></div></div>`:manager&&!['Cancelled','Delivered'].includes(o.status)&&(!isDriver||canDrive(o,user))?`<div class="row order-actions"><button data-delivery="${esc(o.id)}">${isAdmin?'Manage delivery':'Update delivery status'}</button>${isAdmin?`<span class="muted">${o.assigned_to?'Assigned to '+esc(o.assigned_name||o.assigned_to):'No delivery partner assigned'}</span>`:''}</div>`:''}</article>`;}).join('')||`<div class="card"><h3>${list.length?'No matching orders':isDriver?'No deliveries assigned':'No orders yet'}</h3><p>${list.length?'Try another search or status.':isDriver?'The owner must confirm the order and use Send delivery request first.':'Place a demo order to see it here.'}</p></div>`;
 document.querySelectorAll('[data-confirm-order]').forEach(b=>b.onclick=()=>orderDecision(list.find(o=>o.id===b.dataset.confirmOrder),true));
 document.querySelectorAll('[data-reject-order]').forEach(b=>b.onclick=()=>orderDecision(list.find(o=>o.id===b.dataset.rejectOrder),false));
 document.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=action(()=>receiptView(b.dataset.receipt)));
 bindDeliveryActions(list);
 bindAfterSales();
 document.querySelectorAll('[data-delivery]').forEach(b=>b.onclick=()=>deliveryForm(list.find(o=>o.id===b.dataset.delivery)));
 };
 if(isDriver){document.querySelector('#incomingRequests').onclick=()=>{deliveryFilter='requests';draw();};document.querySelector('#acceptedJobs').onclick=()=>{deliveryFilter='accepted';draw();};document.querySelector('#allDeliveries').onclick=()=>{deliveryFilter='all';draw();};}
 document.querySelector('#back').onclick=isDriver?action(orders):action(shop);pageBack(profileOrderContext?profileView:shop,profileOrderContext?'Back to profile':'Back to shop');
 document.querySelector('#orderSearch').oninput=draw;document.querySelector('#orderStatus').onchange=draw;draw();
}
function deliveryForm(o){
 if(user.role==='delivery'&&!canDrive(o,user)){message('Accept this delivery request before changing its status.');return;}
 if(o.status==='Placed'||o.status==='Cancelled'){message('Delivery is unavailable until the owner confirms the order.');return;}
 const isOwner=user.role==='admin',allowed={Placed:['Confirmed','Cancelled'],Confirmed:['Shipped','Cancelled'],Shipped:['Out for delivery','Delivered','Delivery failed'],'Out for delivery':['Delivered','Delivery failed'],'Delivery failed':['Out for delivery'],Delivered:[],Cancelled:[]};
 const choices=(allowed[o.status]||[]).filter(s=>isOwner||['Shipped','Out for delivery','Delivered','Delivery failed'].includes(s));
 view.innerHTML=`<section class="card"><h2>Update delivery</h2><h3>${esc(o.id)}</h3><p>Current status: <strong>${esc(o.status)}</strong></p><form id="deliveryForm"><label>Order / delivery status<select name="status"><option value="${esc(o.status)}">${esc(o.status)} (current)</option>${choices.map(s=>`<option>${s}</option>`).join('')}</select></label><label>Courier / delivery service<input name="courier" maxlength="100" placeholder="Shop delivery, courier name…" value="${esc(o.courier)}"></label><label>Tracking reference<input name="tracking" maxlength="100" value="${esc(o.tracking)}"></label><label>Estimated delivery date<input name="eta" type="date" value="${esc(o.eta)}"></label><label>Delivery update / note<textarea name="note" required minlength="3" maxlength="500" placeholder="e.g. Dispatched from shop, delivery expected tomorrow"></textarea></label><p class="muted">Customers can see this update in My Orders. This demo does not sync with an external courier system.</p><button>Save delivery update</button> <button id="cancelDelivery" type="button" class="secondary">Back</button></form></section>`;
 document.querySelector('#cancelDelivery').onclick=action(orders);
 document.querySelector('#deliveryForm').onsubmit=action(async e=>{const body=Object.fromEntries(new FormData(e.target));if(body.note.trim().length<3)throw Error('Add a short delivery update.');await api((isOwner?'/admin/orders/':'/delivery/orders/')+o.id,'PUT',body);message('Delivery updated. The customer can see the new status and note.');await orders();});
}

(async()=>{try{user=await api('/auth/me');}catch{}restoreCart();navigation();nav.addEventListener('click',e=>{const b=e.target.closest('button[id]');if(b&&b.id!=='logout'&&b.id!=='login')try{sessionStorage.setItem('lastTab',b.id);}catch{}},true);await shop();if(new URLSearchParams(location.search).has('login'))login();else{let last=null;try{last=sessionStorage.getItem('lastTab');}catch{}if(last&&last!=='navShop'){const b=document.getElementById(last);if(b&&nav.contains(b))b.click();}}})().catch(e=>message(e.message));

document.querySelector('#customerSignIn').onclick=()=>{if(adminPath){location.href='/?login=customer';return;}login();};
document.querySelector('#ownerSignIn').onclick=()=>{if(!adminPath){location.href='/?portal=admin&login=owner';return;}login();};



document.querySelector('#deliverySignIn').onclick=()=>{if(!deliveryPath){location.href='/?portal=delivery&login=delivery';return;}login();};

function orderDecision(order,accept){
 view.innerHTML=`<section class="card decision-panel"><h2>${accept?'Confirm':'Reject'} order</h2><h3>${esc(order.id)}</h3><p>${esc(order.name)} · ${esc(order.phone)}</p><p>${esc(order.address)}</p>${order.items.map(i=>`<p class="order-item-name">${itemThumb(i)}<span>${esc(i.name)} × ${i.quantity}</span></p>`).join('')}<p class="price">${money(order.total_paise)}</p><p class="notice">${accept?'Accepting this order allows packing and delivery to proceed.':'Rejecting this order restores its reserved stock. No real refund is processed by this demo.'}</p><div class="row"><button id="commitOrderDecision" class="${accept?'':'danger'}">${accept?'Yes, confirm order':'Yes, reject order'}</button><button id="cancelOrderDecision" class="secondary">Go back</button></div></section>`;
 document.querySelector('#cancelOrderDecision').onclick=action(orders);
 document.querySelector('#commitOrderDecision').onclick=action(async()=>{await api('/admin/orders/'+order.id,'PUT',{status:accept?'Confirmed':'Cancelled',note:accept?'Owner accepted the order. Packing and delivery may now proceed.':'Owner rejected the order before confirmation.'});await orders();message(accept?'Order confirmed. Delivery is now unlocked.':'Order rejected. Reserved stock restored.');});
}
function afterSalesMarkup(order,isAdmin,isDriver){
 if(isDriver)return '';
 const requests=(state.returns||[]).filter(r=>r.order_id===order.id);
 return `<section class="after-sales"><h4>Returns & reviews</h4>${order.items.map(i=>{const request=requests.find(r=>r.product_id===i.product_id),review=(state.reviews||[]).find(r=>r.product_id===i.product_id&&r.email.toLowerCase()===order.email.toLowerCase());return `<div class="after-sales-item"><strong>${esc(i.name)}</strong><p class="policy-tag">${returnLabel(i)}</p>${request?`<div class="return-request"><p><strong>Return ${esc(request.status.toLowerCase())}</strong> · ${esc(request.id)}</p><p>${esc(request.reason)}</p>${request.notes?`<p>Shop response: ${esc(request.notes)}</p>`:''}${request.status==='Received'?'<p class="muted">Item received by shop. Any real refund must be handled separately.</p>':''}${isAdmin&&['Requested','Approved'].includes(request.status)?`<button class="secondary" data-manage-return="${esc(request.id)}">Manage return</button>`:''}</div>`:!isAdmin&&canReturn(order,i)?`<button class="secondary" data-request-return="${esc(order.id)}" data-product="${i.product_id}">Request return</button>`:i.returnable&&order.status==='Delivered'?'<p class="muted">Return window closed or delivery date unavailable.</p>':''}${!isAdmin&&order.status==='Delivered'?` <button class="secondary" data-write-review="${esc(order.id)}" data-product="${i.product_id}">${review?'Edit your review':'Write a review'}</button>`:''}<button class="review-link" data-order-reviews="${i.product_id}">View product reviews</button></div>`;}).join('')}</section>`;
}
function bindAfterSales(){
 document.querySelectorAll('[data-request-return]').forEach(b=>b.onclick=()=>returnForm(b.dataset.requestReturn,+b.dataset.product));
 document.querySelectorAll('[data-manage-return]').forEach(b=>b.onclick=()=>manageReturnForm(b.dataset.manageReturn));
 document.querySelectorAll('[data-write-review]').forEach(b=>b.onclick=()=>reviewForm(b.dataset.writeReview,+b.dataset.product));
 document.querySelectorAll('[data-order-reviews]').forEach(b=>b.onclick=action(()=>reviewsView(+b.dataset.orderReviews)));
}
function returnForm(orderId,productId){
 const order=state.orders.find(o=>o.id===orderId),item=order?.items.find(i=>i.product_id===productId);
 if(!order||!item||!canReturn(order,item)){message('This item is not eligible for return.');return;}
 const deadline=new Date((order.delivered_at+(item.return_days||7)*86400)*1000).toLocaleDateString();
 view.innerHTML=`<section class="card"><h2>Request a return</h2><h3>${esc(item.name)}</h3><p>${esc(order.id)} · Quantity ${item.quantity}</p><p class="policy-tag">${returnLabel(item)} · Request by ${esc(deadline)}</p><form id="returnForm"><label>Why do you want to return this item?<textarea name="reason" required minlength="5" maxlength="1000" placeholder="Describe the issue, such as damaged, faulty, or wrong item"></textarea></label><p class="muted">The owner will review your request. Return approval does not automatically issue a refund.</p><button>Submit return request</button> <button type="button" id="cancelReturn" class="secondary">Cancel</button></form></section>`;
 document.querySelector('#cancelReturn').onclick=action(orders);document.querySelector('#returnForm').onsubmit=action(async e=>{await api('/returns','POST',{order_id:orderId,product_id:productId,reason:new FormData(e.target).get('reason')});await orders();message('Return request submitted. Waiting for the owner to review it.');});
}
function manageReturnForm(id){
 const r=state.returns.find(r=>r.id===id);if(!r)return;
 view.innerHTML=`<section class="card"><h2>Manage return</h2><h3>${esc(r.name)}</h3><p>${esc(r.id)} · ${esc(r.status)}</p><p>Customer reason: ${esc(r.reason)}</p><form id="manageReturnForm"><label>Decision<select name="status">${(r.status==='Requested'?['Approved','Rejected']:['Received']).map(s=>`<option value="${s}">${s==='Received'?'Item received — restore stock':s}</option>`).join('')}</select></label><label>Message to customer<textarea name="notes" required minlength="3" maxlength="1000" placeholder="Add return instructions or explain your decision"></textarea></label><p class="notice">Mark an approved return as received only after the item comes back. Stock is restored once. This demo does not issue real refunds.</p><button>Save return update</button> <button type="button" id="cancelManageReturn" class="secondary">Back</button></form></section>`;
 document.querySelector('#cancelManageReturn').onclick=action(orders);document.querySelector('#manageReturnForm').onsubmit=action(async e=>{await api('/admin/returns/'+r.id,'PUT',Object.fromEntries(new FormData(e.target)));await orders();message('Return request updated.');});
}
async function reviewsView(productId,backTo=shop){
 const product=state.products.find(p=>p.id===productId),reviews=await api('/reviews/'+productId),eligible=user&&state.orders.find(o=>o.email.toLowerCase()===user.email.toLowerCase()&&o.status==='Delivered'&&o.items.some(i=>i.product_id===productId));
 view.innerHTML=`<h2>Customer reviews</h2><h3>${esc(product?.name||'Product')}</h3><p class="price">${ratingSummary(productId)}</p><div class="row"><button id="reviewsBack" class="secondary">Back to shop</button>${eligible?'<button id="addReview">Write / edit your review</button>':'<span class="muted">Reviews can be written after delivery by customers who purchased this item.</span>'}</div><br>${reviews.map(r=>`<article class="card"><div class="row"><strong>${esc(r.display_name)}</strong><span class="brand-tag">Verified purchase</span></div><p class="stars" aria-label="${r.rating} out of 5 stars">${Array.from({length:5},(_,i)=>icon('star',{filled:i<r.rating})).join('')}</p><small>${esc(new Date(r.updated*1000).toLocaleDateString())}</small><p class="review-text">${esc(r.text)}</p>${r.photo?`<img class="review-photo" src="${esc(r.photo)}" alt="Customer photo for ${esc(product?.name||'this product')}">`:''}</article>`).join('')||'<div class="card"><h3>No reviews yet</h3><p>Be the first to share your experience after receiving this product.</p></div>'}`;
 pageBack(backTo,'Back to previous page');document.querySelector('#reviewsBack').onclick=action(backTo);if(eligible)document.querySelector('#addReview').onclick=()=>reviewForm(eligible.id,productId);
}
function reviewForm(orderId,productId){
 const order=state.orders.find(o=>o.id===orderId&&o.email.toLowerCase()===user?.email.toLowerCase()&&o.status==='Delivered'),item=order?.items.find(i=>i.product_id===productId);
 if(!order||!item){message('You can review this item after your order is delivered.');return;}
 const existing=state.reviews.find(r=>r.product_id===productId&&r.email.toLowerCase()===user.email.toLowerCase());let photo=existing?.photo||'',reading=false;
 view.innerHTML=`<section class="card"><h2>${existing?'Edit your':'Write a'} review</h2><h3>${esc(item.name)}</h3><span class="brand-tag">Verified purchase</span><form id="reviewForm"><label style="margin-top:18px">Public display name<input name="display_name" maxlength="60" required value="${esc(existing?.display_name||savedData().profile?.name||'Customer')}"></label><label>Rating<select name="rating" required><option value="">Choose a rating</option>${[5,4,3,2,1].map(n=>`<option value="${n}" ${existing?.rating===n?'selected':''}>${n} ${n===1?'star':'stars'}</option>`).join('')}</select></label><label>Your review<textarea name="text" required minlength="3" maxlength="2000" placeholder="What did you like or dislike about this product?">${esc(existing?.text)}</textarea></label><label>Add a photo (optional)<input type="file" id="reviewPhoto" accept="image/jpeg,image/png,image/webp"></label><small>JPG, PNG, WebP · up to 5 MB. Your name, text, rating, and photo will be visible to people browsing this demo.</small><div id="reviewPhotoPreview" class="photo-preview"></div><button id="removeReviewPhoto" type="button" class="secondary">Remove photo</button><p id="reviewPhotoStatus" role="status"></p><div class="row"><button id="publishReview">Publish review</button><button id="cancelReview" type="button" class="secondary">Cancel</button></div></form></section>`;
 const preview=()=>{document.querySelector('#reviewPhotoPreview').innerHTML=photo?`<img src="${esc(photo)}" alt="Review photo preview">`:'No review photo selected';document.querySelector('#removeReviewPhoto').hidden=!photo;};preview();
 document.querySelector('#reviewPhoto').onchange=async e=>{const file=e.target.files[0];if(!file)return;reading=true;document.querySelector('#publishReview').disabled=true;try{const image=await compressPhoto(file);if(image.length>800000)throw Error('Choose a smaller image.');photo=image;preview();document.querySelector('#reviewPhotoStatus').textContent='Photo ready to publish.';}catch(err){document.querySelector('#reviewPhotoStatus').textContent=err.message;}finally{reading=false;document.querySelector('#publishReview').disabled=false;}};
 document.querySelector('#removeReviewPhoto').onclick=()=>{photo='';document.querySelector('#reviewPhoto').value='';preview();};document.querySelector('#cancelReview').onclick=action(orders);
 document.querySelector('#reviewForm').onsubmit=action(async e=>{if(reading)throw Error('Wait for the photo to finish.');const f=Object.fromEntries(new FormData(e.target));await api('/reviews','POST',{order_id:orderId,product_id:productId,display_name:f.display_name,rating:+f.rating,text:f.text,photo});message('Your review is published and visible to shoppers.');await reviewsView(productId);});
}

