function promotionBanner(){
 const active=state.promotions.filter(p=>p.featured&&promotionStatus(p)==='Active').slice(0,3);
 if(!active.length)return `<section class="ad-banner hero-banner"><div class="hero-copy"><small>• YOUR NEXT UPGRADE</small><h2>Less noise.<br>More life.</h2><p>Find your focus. Explore everyday essentials.</p><button id="bannerOffers">${adminPath?'Create an offer':'Explore the edit'} ${icon('arrow')}</button></div><img class="hero-product" src="/assets/headphones.svg" alt="Studio green over-ear headphones illustration"></section>`;
 return `<section class="ad-banner" aria-label="Shop announcements"><div><small>OFFERS & EVENTS</small>${active.map(p=>`<article class="ad-announcement">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.title)}">`:''}<div><span class="brand-tag">${esc(p.kind)}</span><h2>${esc(p.title)}</h2><p>${esc(p.description)}</p>${p.end?`<small>Through ${esc(p.end)}</small>`:''}</div></article>`).join('')}<button id="bannerOffers">View all offers & events</button></div></section>`;
}
function offersView(filter='All'){
 selectNav('navOffers');
 const owner=adminPath&&user?.role==='admin';
 const items=state.promotions.filter(p=>(owner||promotionStatus(p)==='Active')&&(filter==='All'||p.kind===filter));
 view.innerHTML=`<div class="row" style="justify-content:space-between"><div><h2>${owner?'Manage offers & events':'Offers & events'}</h2><p class="muted">${owner?'Post announcements, schedule dates and feature them on your shop banner.':'Discover current promotions and shop events.'}</p></div>${owner?'<button id="addPromotion">＋ Create promotion</button>':''}</div><div class="category-tabs">${['All','Offer','Event'].map(k=>`<button data-promo-filter="${k}" class="${k===filter?'':'secondary'}">${k==='All'?'All':k==='Offer'?'Offers':'Events'}</button>`).join('')}<button id="offersBack" class="secondary">Back to shop</button></div><div class="grid">${items.map(p=>`<article class="card promotion-card">${p.image?`<img class="promotion-image" src="${esc(p.image)}" alt="${esc(p.title)}">`:''}<div class="row"><span class="brand-tag">${esc(p.kind)}</span>${owner?`<span class="status-pill">${promotionStatus(p)}</span>${p.featured?'<small>Featured on banner</small>':''}`:''}</div><h3>${esc(p.title)}</h3><p class="review-text">${esc(p.description)}</p><p class="muted">${p.start?'From '+esc(p.start):'Available now'}${p.end?' · Through '+esc(p.end):''}</p>${p.terms?`<p><strong>Details & terms</strong><br>${esc(p.terms)}</p>`:''}${owner?`<div class="row"><button data-promo-edit="${esc(p.id)}">Edit</button><button class="secondary" data-promo-toggle="${esc(p.id)}">${p.published?'Unpublish':'Publish'}</button><button class="danger" data-promo-delete="${esc(p.id)}">Delete</button></div>`:''}</article>`).join('')||`<section class="card"><h3>${owner?'No promotions yet':'No current promotions'}</h3><p>${owner?'Create your first offer or event to advertise it here.':'Check back for new offers and events.'}</p></section>`}</div><p class="muted">Promotions are announcements. Checkout uses listed product prices; update product prices to apply a sale.</p>`;
 document.querySelector('#offersBack').onclick=action(shop);
 document.querySelectorAll('[data-promo-filter]').forEach(b=>b.onclick=()=>offersView(b.dataset.promoFilter));
 if(!owner)return;
 document.querySelector('#addPromotion').onclick=()=>promotionForm();
 document.querySelectorAll('[data-promo-edit]').forEach(b=>b.onclick=()=>promotionForm(state.promotions.find(p=>p.id===b.dataset.promoEdit)));
 document.querySelectorAll('[data-promo-toggle]').forEach(b=>b.onclick=action(async()=>{const p=state.promotions.find(p=>p.id===b.dataset.promoToggle);p.published=!p.published;await api('/admin/promotions','PUT',{promotions:state.promotions});offersView(filter);message(p.published?'Promotion published':'Promotion unpublished');}));
 document.querySelectorAll('[data-promo-delete]').forEach(b=>b.onclick=action(async()=>{if(confirm('Delete this promotion?')){state.promotions=state.promotions.filter(p=>p.id!==b.dataset.promoDelete);await api('/admin/promotions','PUT',{promotions:state.promotions});offersView(filter);message('Promotion deleted');}}));
}
function promotionForm(p={}){
 if(!adminPath||user?.role!=='admin')throw Error('Owner access required');
 let image=p.image||'',reading=false;
 view.innerHTML=`<section class="card"><h2>${p.id?'Edit':'Create'} promotion</h2><form id="promotionForm"><label>Type<select name="kind"><option ${p.kind==='Offer'?'selected':''}>Offer</option><option ${p.kind==='Event'?'selected':''}>Event</option></select></label><label>Title<input name="title" required maxlength="100" value="${esc(p.title)}" placeholder="e.g. Weekend headphone sale"></label><label>Announcement<textarea name="description" required minlength="3" maxlength="1000" placeholder="Tell customers what is happening">${esc(p.description)}</textarea></label><div class="form-row"><label>Start date (optional)<input name="start" type="date" value="${esc(p.start)}"></label><label>End date (optional)<input name="end" type="date" value="${esc(p.end)}"></label></div><label>Details, location or terms<textarea name="terms" maxlength="1500" placeholder="Event location, timing, eligible items or conditions">${esc(p.terms)}</textarea></label><label>Advertisement image<input id="promotionPhoto" type="file" accept="image/jpeg,image/png,image/webp"></label><small>JPG, PNG or WebP · up to 5 MB. Stored only in this browser.</small><div id="promotionPreview" class="photo-preview"></div><button id="removePromotionImage" type="button" class="secondary">Remove image</button><label class="radio-label"><input name="featured" type="checkbox" ${p.featured!==false?'checked':''}> Feature in the shop advertising banner</label><label class="radio-label"><input name="published" type="checkbox" ${p.published!==false?'checked':''}> Publish (uncheck to save a draft)</label><p class="muted">Only published promotions within their dates are visible to customers. End dates include the entire day. This announcement does not change product prices.</p><div class="row"><button id="savePromotion">Save promotion</button><button id="cancelPromotion" type="button" class="secondary">Cancel</button></div></form></section>`;
 const preview=()=>document.querySelector('#promotionPreview').innerHTML=image?`<img src="${esc(image)}" alt="Advertisement preview">`:'No image selected';preview();
 document.querySelector('#promotionPhoto').onchange=async e=>{const file=e.target.files[0];if(!file)return;reading=true;document.querySelector('#savePromotion').disabled=true;try{image=await compressPhoto(file);preview();}catch(err){message(err.message);}finally{reading=false;document.querySelector('#savePromotion').disabled=false;}};
 document.querySelector('#removePromotionImage').onclick=()=>{image='';document.querySelector('#promotionPhoto').value='';preview();};
 document.querySelector('#cancelPromotion').onclick=()=>offersView();
 document.querySelector('#promotionForm').onsubmit=action(async e=>{if(reading)throw Error('Wait for the image to finish.');const data=Object.fromEntries(new FormData(e.target));const record=validatePromotion({...data,id:p.id||('PROMO-'+Date.now()+'-'+Math.random().toString(36).slice(2,10)),image,featured:data.featured==='on',published:data.published==='on'});const index=state.promotions.findIndex(x=>x.id===record.id);if(index<0)state.promotions.unshift(record);else state.promotions[index]=record;await api('/admin/promotions','PUT',{promotions:state.promotions});offersView();message('Promotion saved. Active featured promotions appear on your shop banner.');});
}

// Delivery request and map UI. Local storage is shared across portals on this origin only.
let activeMap=null,activeMapElement=null,trackingOrderId=null,geoWatch=null,sharingRequestId=null;
function reloadLocal(){}
function captureLocation(done,status){
 if(!deviceLocation){status.textContent='Location is unavailable in this browser. Enter coordinates manually.';return;}
 status.textContent='Waiting for location permission…';
 deviceLocation.getCurrentPosition(pos=>{done({lat:+pos.coords.latitude.toFixed(6),lng:+pos.coords.longitude.toFixed(6)});status.textContent='Location added. Check that the pin matches the intended address.';},err=>{status.textContent=err.code===1?'Location permission denied. Search an area or choose a pin on the map.':'Could not get location. Search an area or choose a map pin.';},{enableHighAccuracy:true,timeout:15000,maximumAge:30000});
}
function stopSharing(note='Location sharing stopped.'){
 if(geoWatch!==null)deviceLocation?.clearWatch(geoWatch);geoWatch=null;sharingRequestId=null;
 const hint=document.querySelector('#sharingStatus');if(hint)hint.textContent=note;
 const start=document.querySelector('#startSharing'),stop=document.querySelector('#stopSharing');if(start)start.disabled=false;if(stop)stop.disabled=true;
}
function disposeMap(){stopSharing();activeMap?.remove();activeMap=null;activeMapElement=null;trackingOrderId=null;}
new MutationObserver(()=>{if(activeMapElement&&!activeMapElement.isConnected)disposeMap();}).observe(view,{childList:true});
window.addEventListener('beforeunload',()=>stopSharing());
function deliveryRequestMarkup(o,isOwner,isDriver){
 const r=o.delivery_request,loc=o.locations;
 if(o.status==='Placed')return '';
 return `<section class="delivery-request-panel"><div class="row"><span class="request-icon">${icon('truck')}</span><h4>Delivery ${r?'request · '+esc(r.status):'assignment'}</h4></div>${r?`<p>${esc(r.note||'Owner sent a delivery request.')}</p><p class="muted">Sent ${esc(new Date(r.created_at*1000).toLocaleString())}${r.responded_at?' · Responded '+esc(new Date(r.responded_at*1000).toLocaleString()):''}</p>${r.response_note?`<p>Partner response: ${esc(r.response_note)}</p>`:''}`:'<p class="muted">The owner can send a delivery request after confirming the order.</p>'}${loc?`<div class="delivery-addresses"><div><strong>${icon('box')} Pickup</strong><p>${esc(loc.pickup.label)}</p></div><div><strong>${icon('pin')} Deliver to</strong><p>${esc(o.name)} · ${esc(o.phone)}</p><p>${esc(o.address)}</p></div></div>`:''}<div class="row">${isOwner&&o.status==='Confirmed'&&!['Pending','Accepted'].includes(r?.status)?`<button data-send-request="${esc(o.id)}">${icon('truck')} Send delivery request</button>`:''}${isOwner&&o.status==='Confirmed'&&['Pending','Accepted'].includes(r?.status)?`<button class="secondary" data-withdraw-request="${esc(o.id)}">Withdraw request</button>`:''}${isDriver&&o.status==='Confirmed'&&r?.status==='Pending'?`<button data-accept-request="${esc(o.id)}">${icon('check')} Accept request</button><button class="secondary" data-decline-request="${esc(o.id)}">Decline request</button>`:''}${loc?`<button class="secondary" data-track-order="${esc(o.id)}">${icon('pin')} Map & tracking</button>`:''}</div></section>`;
}
function bindDeliveryActions(list){
 const get=id=>list.find(o=>o.id===id);
 document.querySelectorAll('[data-send-request]').forEach(b=>b.onclick=()=>deliveryRequestForm(get(b.dataset.sendRequest)));
 document.querySelectorAll('[data-withdraw-request]').forEach(b=>b.onclick=action(async()=>{if(confirm('Withdraw this delivery request?')){await api('/admin/withdraw-delivery/'+b.dataset.withdrawRequest,'POST',{});await orders();message('Delivery request withdrawn.');}}));
 document.querySelectorAll('[data-accept-request]').forEach(b=>b.onclick=action(async()=>{const o=get(b.dataset.acceptRequest);await api('/delivery/requests/'+o.id,'POST',{request_id:o.delivery_request.id,decision:'Accepted'});await orders();message('Request accepted. You can now update the delivery and share location.');}));
 document.querySelectorAll('[data-decline-request]').forEach(b=>b.onclick=()=>declineRequestForm(get(b.dataset.declineRequest)));
 document.querySelectorAll('[data-track-order]').forEach(b=>b.onclick=()=>trackingView(get(b.dataset.trackOrder)));
}
function declineRequestForm(o){
 view.innerHTML=`<section class="card"><h2>Decline delivery request</h2><p>${esc(o.id)}</p><form id="declineForm"><label>Reason (optional)<textarea name="note" maxlength="500" placeholder="Unavailable, outside delivery area…"></textarea></label><button>Decline request</button><button class="secondary" id="cancelDecline" type="button">Go back</button></form></section>`;
 document.querySelector('#cancelDecline').onclick=action(orders);document.querySelector('#declineForm').onsubmit=action(async e=>{await api('/delivery/requests/'+o.id,'POST',{request_id:o.delivery_request.id,decision:'Declined',note:new FormData(e.target).get('note')});await orders();message('Request declined. The owner can send a new request.');});
}
function deliveryRequestForm(o){
 if(user?.role!=='admin'||o.status!=='Confirmed'){message('Confirm this order before sending a delivery request.');return;}
 disposeMap();const pickup=o.locations?.pickup||state.deliveryPickup||{},dropoff=o.locations?.dropoff||o.destination||{};
 view.innerHTML=`<section class="card"><h2>${icon('truck')} Send delivery request</h2><p>${esc(o.id)} · ${esc(o.name)} · ${esc(o.phone)}</p><p><strong>Customer delivery address</strong><br>${esc(o.address)}</p><form id="deliveryRequestForm"><label>Delivery partner<select name="assigned_to" required>${(state.delivery_partners||[]).map(p=>`<option value="${esc(p.email)}">${esc(p.name)} · ${esc(p.email)}</option>`).join('')||'<option value="">No delivery partners - set DELIVERY_EMAILS on the server</option>'}</select></label><label>Pickup address<textarea name="pickup_address" required minlength="5" maxlength="500" placeholder="Shop name, street, city…">${esc(pickup.label)}</textarea></label><div id="requestPlace"></div><input id="pickupLat" type="hidden" value="${esc(pickup.lat)}"><input id="pickupLng" type="hidden" value="${esc(pickup.lng)}"><input id="dropoffLat" type="hidden" value="${esc(dropoff.lat)}"><input id="dropoffLng" type="hidden" value="${esc(dropoff.lng)}"><label>Click the map to choose<select id="pinTarget"><option value="dropoff">Customer drop-off pin</option><option value="pickup">Shop pickup pin</option></select></label><button id="captureRequestPin" class="secondary" type="button">${icon('pin')} Use my current location for selected pin</button><p id="requestGeoStatus" role="status" class="muted">Search an area for the selected pin, use GPS, or click the map. Check both pins before sending.</p><div id="requestMap" class="delivery-map" role="region" aria-label="Choose pickup and delivery map pins"></div><label>Request note<textarea name="note" maxlength="500" placeholder="Collection timing or delivery instructions…">Please collect this confirmed order from the shop.</textarea></label><p class="notice">The partner must accept before dispatch. In local mode this request appears in the delivery portal on this browser and origin; it is not sent to another phone.</p><div class="row"><button>${icon('truck')} Send request</button><button type="button" id="cancelDeliveryRequest" class="secondary">Cancel</button></div></form></section>`;
 const points=()=>({pickup:point({lat:document.querySelector('#pickupLat').value,lng:document.querySelector('#pickupLng').value},true),dropoff:point({lat:document.querySelector('#dropoffLat').value,lng:document.querySelector('#dropoffLng').value},true)});
 const refreshPins=()=>{try{activeMap?.update(points());}catch(err){document.querySelector('#requestGeoStatus').textContent=err.message;}};
 const fill=p=>{const target=document.querySelector('#pinTarget').value;document.querySelector('#'+target+'Lat').value=p.lat;document.querySelector('#'+target+'Lng').value=p.lng;refreshPins();};
 placeSearch(document.querySelector('#requestPlace'),fill);
 activeMapElement=document.querySelector('#requestMap');activeMap=createDeliveryMap(activeMapElement,{pickup:point(pickup,true),dropoff:point(dropoff,true),onPick:fill});
 ['pickupLat','pickupLng','dropoffLat','dropoffLng'].forEach(id=>document.getElementById(id).onchange=refreshPins);
 document.querySelector('#captureRequestPin').onclick=()=>captureLocation(fill,document.querySelector('#requestGeoStatus'));
 document.querySelector('#cancelDeliveryRequest').onclick=action(orders);
 document.querySelector('#deliveryRequestForm').onsubmit=action(async e=>{const f=Object.fromEntries(new FormData(e.target)),p=points();await api('/admin/delivery-requests/'+o.id,'POST',{...f,...p});await orders();message('Delivery request sent. Waiting for the partner to accept.');});
}
function trackingView(order){
 disposeMap();reloadLocal();const o=state.orders.find(x=>x.id===order.id);if(!o?.locations){message('The owner needs to add pickup and drop-off pins first.');return;}
 const driver=canDrive(o,user);
 view.innerHTML=`<section class="card"><div class="row"><h2>${icon('pin')} Delivery map</h2><span class="status-pill">${esc(o.status)}</span></div><p>${esc(o.id)}</p><div class="delivery-addresses"><div><strong>Pickup</strong><p>${esc(o.locations.pickup.label)}</p></div><div><strong>Drop-off</strong><p>${esc(o.name)} · ${esc(o.phone)}</p><p>${esc(o.address)}</p></div></div><div id="trackingMap" class="delivery-map" role="region" aria-label="Delivery tracking map"></div><div class="map-legend"><span><i class="legend-dot pickup"></i> Shop</span><span><i class="legend-dot dropoff"></i> Customer</span><span><i class="legend-dot driver"></i> Partner</span></div><p id="locationSummary" role="status"></p><p id="distanceSummary" class="muted"></p><p class="muted">The dashed connection is straight-line distance, not a road route or arrival estimate. Map tiles require internet.</p>${driver?`<section class="sharing-panel"><h3>${icon('navigation')} Share your location</h3><p>Your browser will ask permission. Sharing runs while this tracking view stays open and stops when you leave it. The latest point is retained for tracking.</p><div class="row"><button id="startSharing">Start GPS sharing</button><button id="stopSharing" class="secondary" disabled>Stop sharing</button></div><p id="sharingStatus" role="status">Location sharing is off.</p><details><summary>Enter a location manually</summary><div id="manualPlace"></div></details></section>`:''}<p class="notice">Local tracking preview: updates are visible across tabs/portals in this browser only. Different devices require a shared backend. No location is generated or simulated.</p><button id="trackingBack" class="secondary">Back to orders</button></section>`;
 activeMapElement=document.querySelector('#trackingMap');activeMap=createDeliveryMap(activeMapElement,{...o.locations,driver:o.driver_location,trail:o.location_trail});trackingOrderId=o.id;
 updateTracking();document.querySelector('#trackingBack').onclick=action(orders);
 if(driver){document.querySelector('#stopSharing').onclick=()=>stopSharing();
 document.querySelector('#startSharing').onclick=()=>{
  if(!deviceLocation){message('Geolocation is unavailable. Enter a manual location.');return;}if(geoWatch!==null)return;
  sharingRequestId=o.delivery_request.id;document.querySelector('#startSharing').disabled=true;document.querySelector('#stopSharing').disabled=false;document.querySelector('#sharingStatus').textContent='Waiting for GPS permission and first position…';
  geoWatch=deviceLocation.watchPosition(async pos=>{const requestId=sharingRequestId;if(!requestId)return;try{await api('/delivery/location/'+o.id,'POST',{request_id:requestId,lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy,source:'gps'});if(requestId!==sharingRequestId)return;updateTracking();const status=document.querySelector('#sharingStatus');if(status)status.textContent='GPS sharing is on. Latest position updated.';}catch(err){stopSharing(err.message);}},err=>{stopSharing(err.code===1?'Permission denied. Enter a manual location instead.':'GPS unavailable or timed out. Try again or enter a manual location.');},{enableHighAccuracy:true,maximumAge:5000,timeout:20000});
 };
 placeSearch(document.querySelector('#manualPlace'),async p=>{await api('/delivery/location/'+o.id,'POST',{lat:p.lat,lng:p.lng,request_id:o.delivery_request.id,source:'manual',label:p.label});updateTracking();message('Area location updated (manually selected, not live GPS).');});}
}
function updateTracking(){
 const o=state.orders.find(x=>x.id===trackingOrderId);if(!o||!activeMap)return;
 activeMap.update({...o.locations,driver:o.driver_location,trail:o.location_trail});
 const p=o.driver_location,summary=document.querySelector('#locationSummary');if(summary)summary.textContent=p?`${p.source==='manual'?'Manually entered position':'Last GPS position'}: ${esc(o.driver_area||'Location shown on the map')} · Updated ${new Date(p.at*1000).toLocaleString()}${p.accuracy!=null?' · Accuracy ±'+Math.round(p.accuracy)+' m':''}${Date.now()/1000-p.at>120?' · This position is more than 2 minutes old.':''}`:'Waiting for the delivery partner to share a location.';
 const distance=document.querySelector('#distanceSummary');if(distance)distance.textContent=p?`${distanceKm(p,o.locations.dropoff).toFixed(2)} km straight-line distance to customer`:'';
 if(geoWatch!==null&&(!canDrive(o,user)||sharingRequestId!==o.delivery_request?.id))stopSharing('Sharing stopped: this delivery is no longer active or assigned.');
}
// Live tracking: poll the server while a tracking map is open (data now lives on the server, not in this browser).
setInterval(async()=>{if(document.hidden||!trackingOrderId)return;try{await refreshState();if(trackingOrderId)updateTracking();}catch{}},10000);

function customerSignIn(destination){
 const c=storedCustomer()||{};
 view.innerHTML=`<section class="card"><h2>Sign in</h2><p class="muted">Sign in to save your cart, place orders and track repairs.</p><form id="customerSignIn"><label>Full name<input name="name" required minlength="2" maxlength="80" autocomplete="name" value="${esc(c.name)}"></label><label>Email<input name="email" type="email" required maxlength="254" autocomplete="email" value="${esc(c.email)}"></label><label>Phone (optional)<input name="phone" inputmode="tel" maxlength="16" autocomplete="tel" value="${esc(c.phone)}"></label><button>Sign in</button> <button id="signInBack" type="button" class="secondary">Keep browsing</button></form></section>`;
 if(deliveryPath||adminPath){view.querySelector('h2').textContent=deliveryPath?'Delivery partner sign in':'Owner sign in';view.querySelector('p').textContent=deliveryPath?'Sign in with the email the shop registered for you. We will send you a 6-digit code.':'Sign in with your owner email. We will send you a 6-digit code.';document.querySelector('#signInBack').remove();}
 else document.querySelector('#signInBack').onclick=action(shop);
 document.querySelector('#customerSignIn').onsubmit=action(async e=>{const c=validateCustomer(Object.fromEntries(new FormData(e.target)));const r=await requestOtp(c);otpStep(c,r.message,destination);});
}
function otpStep(c,note,destination){
 view.innerHTML=`<section class="card"><h2>Enter your code</h2><p class="muted">${esc(note)}</p><form id="otpForm"><label>6-digit code<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required autofocus></label><button>Verify and sign in</button> <button id="otpResend" type="button" class="secondary">Resend code</button> <button id="otpBack" type="button" class="secondary">Change details</button></form></section>`;
 document.querySelector('#otpBack').onclick=()=>customerSignIn(destination);
 document.querySelector('#otpResend').onclick=action(async()=>{const r=await requestOtp(c);message(r.message);});
 document.querySelector('#otpForm').onsubmit=action(async e=>{const v=await verifyOtp(c.email,new FormData(e.target).get('code').trim());user={email:v.email,name:v.name,phone:v.phone,role:v.role||'customer'};await refreshState();mergeGuest();restoreCart();const d=savedData();d.profile={...d.profile,name:d.profile?.name||v.name,phone:d.profile?.phone||v.phone};save();navigation();message('Signed in as '+v.name);if(destination==='profile')profileView();else if(destination==='orders')orders();else if(destination==='checkout')checkoutForm();else shop();});
}
const pageNames={navShop:'Shop',navWishlist:'Wishlist',navCart:'Cart',orders:'Orders',navProfile:'Profile',navOffers:'Offers',navRepairs:'Repair Centre'};
function selectNav(id){if(pageNames[id])track('view',user,{page:pageNames[id]});nav.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.id===id);if(b.id===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}

const stepperHtml=p=>{const n=cart[p.id]||0;const name=esc(p.name);return n?`<button class="qty-btn" data-less-card="${p.id}" aria-label="Remove one ${name} from cart">${icon('minus')}</button><span class="qty-count" aria-live="polite">${n}</span><button class="qty-btn" data-add="${p.id}" aria-label="Add another ${name} to cart" ${n>=p.stock?'disabled':''}>${icon('plus')}</button>`:`<button class="quick-add" data-add="${p.id}" aria-label="Add ${name} to cart" title="Add to cart" ${p.stock?'':'disabled'}>${icon('plus')}</button>`};
function refreshStepper(id){const p=state.products.find(p=>p.id===+id);if(!p)return;document.querySelectorAll(`[data-stepper="${id}"]`).forEach(el=>{el.innerHTML=stepperHtml(p);el.classList.toggle('has-qty',!!cart[id]);el.classList.remove('qty-bump');void el.offsetWidth;el.classList.add('qty-bump');});bindSteppers();}
function bindSteppers(){document.querySelectorAll('[data-stepper] [data-add]').forEach(b=>b.onclick=action(()=>addItem(b.dataset.add)));document.querySelectorAll('[data-less-card]').forEach(b=>b.onclick=action(()=>{const id=b.dataset.lessCard;const name=state.products.find(p=>p.id===+id)?.name||'Item';if(--cart[id]<=0)delete cart[id];saveCart();refreshStepper(+id);message(cart[id]?name+' quantity: '+cart[id]:name+' removed from cart');}));}
function cartFeedback(id){
 refreshStepper(id);document.querySelectorAll(`[data-stepper="${id}"],#detailAdd`).forEach(el=>{if(el.id==='detailAdd'&&!document.querySelector('.product-details-page'))return;const t=document.createElement('span');t.className='qty-tick';t.setAttribute('aria-hidden','true');t.innerHTML='<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="m5 12 5 5 9-10"/></svg>';el.append(t);setTimeout(()=>t.remove(),1300);});
 const target=document.querySelector('#navCart');if(!target)return;target.classList.remove('cart-confirm');void target.offsetWidth;target.classList.add('cart-confirm');target.addEventListener('animationend',()=>target.classList.remove('cart-confirm'),{once:true});
}
function receiptView(id){
 reloadLocal();const order=state.orders.find(o=>o.id===id&&(user?.role==='admin'||o.email.toLowerCase()===user?.email.toLowerCase()));if(!order)throw Error('This receipt is not available for this account.');const r=receiptData(order);
 view.innerHTML=`<div class="row receipt-toolbar"><button id="downloadReceipt">Download receipt</button><button id="printReceipt" class="secondary">Print / Save as PDF</button><button id="backFromReceipt" class="secondary">Back to orders</button></div>${receiptMarkup(order)}`;
 document.querySelector('#downloadReceipt').onclick=()=>{const blob=new Blob([receiptDocument(order)],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=r.id.replace(/[^a-zA-Z0-9_-]/g,'_')+'.html';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);};
 document.querySelector('#printReceipt').onclick=()=>window.print();document.querySelector('#backFromReceipt').onclick=action(orders);
}

function repairCentre(){
 disposeMap();reloadLocal();selectNav('navRepairs');if(!user){login();return;}
 const owner=user.role==='admin';const records=(state.repairs||[]).filter(r=>owner||r.email===user.email);
 view.innerHTML=`<section id="repairCentre"><div class="row"><h2>Repair Centre</h2>${!owner?'<button id="newRepair">Book a repair</button>':''}</div><p>Upload your device and describe the problem. Track its repair ID, price and shop messages here.</p><p class="notice">Local preview: updates appear in this browser only. Messages are in-app, not SMS or WhatsApp.</p><label>Find repair by ID or item<input id="repairSearch" placeholder="REP-… or laptop"></label><div id="repairList"></div></section>`;
 const draw=()=>{const q=document.querySelector('#repairSearch').value.trim().toLowerCase();document.querySelector('#repairList').innerHTML=records.filter(r=>[r.id,r.item].some(x=>x.toLowerCase().includes(q))).map(r=>`<article class="card"><div class="row"><h3>${esc(r.item)}</h3><span class="status-pill">${esc(r.status)}</span></div><strong>${esc(r.id)}</strong><p>${esc(r.problem)}</p><img class="repair-photo" src="${esc(r.photo)}" alt="${esc(r.item)} submitted for repair"><p>Repair price: <strong>${r.price_paise===null?'To be assessed':money(r.price_paise)}</strong></p>${owner?`<p>Customer: ${esc(r.email)}</p><button data-repair-edit="${esc(r.id)}">Update repair / message customer</button>`:''}<h4>Shop messages</h4>${r.messages.length?r.messages.map(m=>`<p class="repair-message">${esc(m.text)}<br><small>${new Date(m.at).toLocaleString('en-IN')}</small></p>`).join(''):'<p class="muted">The owner will update you here.</p>'}<details><summary>Status history</summary>${r.history.map(h=>`<p>${esc(h.status)} · ${new Date(h.at).toLocaleString('en-IN')}</p>`).join('')}</details></article>`).join('')||'<p>No repair requests found.</p>';document.querySelectorAll('[data-repair-edit]').forEach(b=>b.onclick=()=>repairUpdate(b.dataset.repairEdit));};
 document.querySelector('#repairSearch').oninput=draw;draw();if(!owner)document.querySelector('#newRepair').onclick=repairBooking;
}
function repairBooking(){
 view.innerHTML=`<section class="card"><h2>Book a repair</h2><form id="repairForm"><label>Item / model<input name="item" maxlength="120" required minlength="2" placeholder="e.g. HP Pavilion laptop"></label><label>Describe the problem<textarea name="problem" minlength="10" maxlength="2000" required placeholder="What stopped working? When did it start?"></textarea></label><label>Upload item photo<input id="repairPhoto" type="file" accept="image/jpeg,image/png,image/webp" required></label><img id="repairPhotoPreview" hidden alt="Repair item photo preview"><p id="repairPhotoStatus" role="status"></p><button id="submitRepair">Submit repair request</button> <button id="cancelRepair" type="button" class="secondary">Back</button></form></section>`;
 let photo='',reading=false;document.querySelector('#repairPhoto').onchange=async e=>{photo='';const file=e.target.files[0];document.querySelector('#repairPhotoPreview').hidden=true;if(!file)return;reading=true;document.querySelector('#submitRepair').disabled=true;try{photo=await compressPhoto(file);const img=document.querySelector('#repairPhotoPreview');img.src=photo;img.hidden=false;document.querySelector('#repairPhotoStatus').textContent='Photo ready.';}catch(err){message(err.message);}finally{reading=false;document.querySelector('#submitRepair').disabled=false;}};
 document.querySelector('#cancelRepair').onclick=repairCentre;
 document.querySelector('#repairForm').onsubmit=action(async e=>{if(reading)throw Error('Wait for the photo.');const r=await api('/repairs','POST',{...Object.fromEntries(new FormData(e.target)),photo});track('repair_booked',user,{item:r.item,order_id:r.id});repairCentre();message('Repair request submitted. Your tracking ID: '+r.id);});
}
function repairUpdate(id){
 reloadLocal();if(user?.role!=='admin')throw Error('Owner access required.');const r=state.repairs?.find(r=>r.id===id);if(!r)throw Error('Repair not found.');
 view.innerHTML=`<section class="card"><h2>Update repair</h2><p>${esc(r.id)} · ${esc(r.item)}</p><p>${esc(r.problem)}</p><form id="repairUpdateForm"><label>Repair status<select name="status">${repairStatuses.map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></label><label>Repair price (₹)<input name="price" type="number" min="0" max="1000000" step="0.01" value="${r.price_paise===null?'':r.price_paise/100}" placeholder="Leave blank until assessed"></label><label>Message to customer<textarea name="message" maxlength="1000" placeholder="Repair progress or collection instructions"></textarea></label><p class="muted">Ready for pickup automatically adds an in-app collection message. No money is charged here.</p><button>Save and notify customer in app</button> <button id="cancelRepairUpdate" type="button" class="secondary">Back</button></form></section>`;
 document.querySelector('#cancelRepairUpdate').onclick=repairCentre;document.querySelector('#repairUpdateForm').onsubmit=action(async e=>{const f=Object.fromEntries(new FormData(e.target));await api('/repairs/'+id,'PUT',f);repairCentre();message('Repair updated. The customer can see the status, price and messages in Repair Centre.');});
}
function placeSearch(host,onSelect){
 host.innerHTML='<label>Area / city / landmark<input class="place-query" placeholder="e.g. Mansarovar, Jaipur" maxlength="200"></label><button type="button" class="secondary place-find">Find area</button><p class="muted">Search sends this area name to Photon / OpenStreetMap. Select the correct result; a place pin is approximate.</p><div class="place-results" role="status"></div>';
 const input=host.querySelector('.place-query'),results=host.querySelector('.place-results');
 input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();host.querySelector('.place-find').click();}};input.oninput=()=>{results.textContent='';};host.querySelector('.place-find').onclick=action(async()=>{const q=input.value.trim();if(q.length<3)throw Error('Enter an area and city (at least 3 characters).');results.textContent='Finding places…';try{const response=await fetch('https://photon.komoot.io/api/?q='+encodeURIComponent(q)+'&limit=5',{signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error('Area search unavailable.');const data=await response.json();if(input.value.trim()!==q)return;const matches=(data.features||[]).map(f=>({lat:f.geometry?.coordinates?.[1],lng:f.geometry?.coordinates?.[0],label:[f.properties?.name,f.properties?.city,f.properties?.state,f.properties?.country].filter(Boolean).join(', ')})).filter(p=>p.label&&Number.isFinite(p.lat)&&Number.isFinite(p.lng));results.innerHTML=matches.length?matches.map((p,i)=>`<button type="button" class="secondary" data-place="${i}">${esc(p.label)}</button>`).join(''):'No places found. Add a city or use GPS / the map.';results.querySelectorAll('[data-place]').forEach(b=>b.onclick=action(async()=>{await onSelect(matches[+b.dataset.place]);results.textContent='Selected: '+matches[+b.dataset.place].label;}));}catch{results.textContent='Area search is unavailable. Use current location or choose a map pin.';}});
}

function refreshCategories(){
 categories=['Laptop','Charger','Camera','Headphone','Speaker','Microphone','Other',...(state.customCategories||[]).map(c=>c.id)];
 for(const c of state.customCategories||[])categoryLabels[c.id]=c.name;
}
function categoryIcon(id){return icons[id]||icon((state.customCategories||[]).find(c=>c.id===id)?.icon||'box');}
function categoryManager(){
 if(user?.role!=='admin')throw Error('Only the owner can manage categories.');reloadLocal();refreshCategories();selectNav('navShop');
 view.innerHTML=`<section class="card"><h2>Manage categories</h2><p>Create a category, then add products to it. Existing products can be moved using Edit product.</p><form id="categoryForm"><label>New category name<input name="name" required minlength="2" maxlength="40" placeholder="e.g. Monitors"></label><label>Category icon<select name="icon">${['box','laptop','camera','headphones','speaker','mic','charger'].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></label><button>Create category</button><button id="categoryBack" type="button" class="secondary">Back to products</button></form></section><section class="grid">${categories.map(c=>`<article class="card"><span class="category-icon">${categoryIcon(c)}</span><h3>${esc(categoryLabels[c])}</h3><p>${state.products.filter(p=>p.active&&p.category===c).length} items</p><button data-category-item="${esc(c)}">Add item to ${esc(categoryLabels[c])}</button></article>`).join('')}</section>`;
 document.querySelector('#categoryBack').onclick=action(shop);
 document.querySelectorAll('[data-category-item]').forEach(b=>b.onclick=()=>productForm({category:b.dataset.categoryItem}));
 document.querySelector('#categoryForm').onsubmit=action(async e=>{reloadLocal();refreshCategories();const f=Object.fromEntries(new FormData(e.target));const name=String(f.name||'').trim().replace(/\s+/g,' ');if(name.length<2||name.length>40)throw Error('Enter a category name from 2 to 40 characters.');if(categories.some(c=>categoryLabels[c].toLocaleLowerCase()===name.toLocaleLowerCase())||categories.some(c=>c.toLocaleLowerCase()===name.toLocaleLowerCase()))throw Error('This category already exists.');const id='CAT-'+Array.from(crypto.getRandomValues(new Uint8Array(8)),n=>n.toString(16).padStart(2,'0')).join('');await api('/admin/categories','POST',{name,icon:f.icon});categoryManager();message('Category created. Choose Add item to '+name+' to add its products.');});
}

function deliveryProfile(){
 disposeMap();selectNav('navProfile');
 const mine=state.orders||[],active=mine.filter(o=>o.delivery_request?.status==='Accepted'&&!['Delivered','Cancelled'].includes(o.status)).length,pending=mine.filter(o=>o.delivery_request?.status==='Pending').length,done=mine.filter(o=>o.status==='Delivered').length;
 view.innerHTML=`<section class="card delivery-profile"><h2>${esc(user.name||'Delivery partner')}</h2><p class="muted">${esc(user.email)}${user.phone?' · '+esc(user.phone):''}</p>
 <div class="admin-stats"><div class="card"><small>New requests</small><strong>${pending}</strong></div><div class="card"><small>Active deliveries</small><strong>${active}</strong></div><div class="card"><small>Delivered</small><strong>${done}</strong></div></div>
 <div class="row"><button id="profileJobs">View requests & deliveries</button><button id="profileSignOut" class="secondary">Sign out</button></div></section>`;
 document.querySelector('#profileJobs').onclick=action(async()=>{await orders();selectNav('orders');});
 document.querySelector('#profileSignOut').onclick=action(async()=>{await api('/auth/logout','POST');user=null;navigation();login();});
}
function profileView(){
 if(deliveryPath&&user?.role==='delivery'){deliveryProfile();return;}
 disposeMap();reloadLocal();selectNav('navProfile');if(!user){login('profile');return;}
 const data=savedData(),profile=data.profile||{},myOrders=state.orders.filter(o=>o.email.toLowerCase()===user.email.toLowerCase());
 const name=profile.name||({admin:'Shop owner',delivery:'Delivery partner',customer:'Customer'})[user.role]||'Customer';
 const row=(id,symbol,title,subtitle='')=>`<button class="profile-menu-row" id="${id}"><span class="profile-row-icon">${icon(symbol)}</span><span class="profile-row-copy"><strong>${title}</strong>${subtitle?`<small>${subtitle}</small>`:''}</span>${icon('chevron')}</button>`;
 view.innerHTML=`<section class="profile-home"><div class="profile-greeting"><button class="profile-avatar" id="chooseAvatar" aria-label="Choose profile avatar">${avatarMarkup(data.avatarKey||'lime',name)}</button><div><h2>Hello, ${esc(name)}!</h2><p>${esc(user.email)}</p><span class="profile-account-label">Local demo account</span></div><button class="icon-button" id="editProfile" aria-label="Edit personal details">${icon('edit')}</button></div><div class="profile-metrics"><button id="profileOrdersCount"><strong>${myOrders.length}</strong><span>Orders</span></button><button id="profileWishlistCount"><strong>${data.wishlist.length}</strong><span>Wishlist</span></button></div><section class="profile-menu-group"><h3>My shopping</h3>${row('profileOrders','box','My Orders','Track, return and view receipts')}${row('profileWishlist','heart','My Wishlist','Your saved products')}${row('profileAddresses','pin','Saved Addresses','Manage delivery locations')}${row('profilePayments','card','Payment Methods','Checkout payment options')}${row('profileReturns','refresh','Returns & Refunds','Track your return requests')}</section><section class="profile-menu-group"><h3>Account & support</h3>${row('profileDevices','laptop','My Repair Devices')}${row('profilePrivacy','shield','Security & Privacy')}${row('profileNotifications','bell','Notifications')}${row('profileHelp','headphones','Help & Support')}${row('profileLogout','logout','Logout')}</section></section>`;
 document.querySelector('#chooseAvatar').onclick=avatarPicker;
 document.querySelector('#editProfile').onclick=()=>profileDetailsView();
 ['profileOrders','profileOrdersCount'].forEach(id=>document.getElementById(id).onclick=action(()=>{profileOrderContext=true;return orders();}));
 ['profileWishlist','profileWishlistCount'].forEach(id=>document.getElementById(id).onclick=()=>{collectionReturnTo=profileView;collectionView('wishlist');});
 ['profileAddresses'].forEach(id=>document.getElementById(id).onclick=()=>profileDetailsView('addresses'));
 for(const name of ['Payments','Returns','Devices','Privacy','Notifications','Help'])document.getElementById('profile'+name).onclick=()=>profilePanel(name);
 document.querySelector('#profileLogout').onclick=action(async()=>{await api('/auth/logout','POST');user=null;restoreCart();navigation();login('profile');});
}
function profilePanel(kind){
 reloadLocal();if(!user){login('profile');return;}selectNav('navProfile');const mine=(state.repairs||[]).filter(r=>r.email.toLowerCase()===user.email.toLowerCase());
 const titles={Payments:'Payment Methods',Returns:'Returns & Refunds',Devices:'My Repair Devices',Privacy:'Security & Privacy',Notifications:'Notifications',Help:'Help & Support'};
 let content='';
 if(kind==='Payments')content='<h3>Cash on delivery</h3><p>Choose cash on delivery during checkout. The owner must confirm your order before dispatch.</p><h3>Online payment preview</h3><p>UPI, card and net banking are simulations. No money is collected and no payment credentials are stored.</p>';
 if(kind==='Privacy')content='<p>This is a local demo account. Email and identity have not been verified. Personal details, addresses, photos, orders and repairs stay in this browser or app installation.</p><p>Supabase is disconnected. This preview has no secure shared account system. Clearing browser/app data can remove local records.</p><p>GPS is requested only when you choose a location action. Delivery sharing stops when you leave the tracking screen. Area searches send the area name to Photon; map tiles require internet.</p>';
 if(kind==='Returns'){const list=(state.returns||[]).filter(r=>r.email?.toLowerCase()===user.email.toLowerCase()||state.orders.some(o=>o.id===r.order_id&&o.email.toLowerCase()===user.email.toLowerCase()));content=list.length?list.map(r=>`<article class="card"><strong>${esc(r.id)}</strong><p>${esc(state.products.find(p=>p.id===r.product_id)?.name||'Item')} · ${esc(r.status)}</p><p>${esc(r.reason)}</p>${r.notes?`<p>Shop response: ${esc(r.notes)}</p>`:''}</article>`).join(''):'<p>No return requests yet. Open a delivered order to request a return when its item policy allows it.</p>';content+='<p>Real refunds are handled separately by the shop in this preview.</p><button id="panelOrders">Open my orders</button>';}
 if(kind==='Devices')content=mine.length?mine.map(r=>`<article class="card"><h3>${esc(r.item)}</h3><p>${esc(r.id)} · ${esc(r.status)}</p><p>${esc(r.problem)}</p></article>`).join(''):'<p>No devices submitted for repair yet. Devices appear here after you book a repair.</p>';
 if(kind==='Notifications'){const messages=mine.flatMap(r=>r.messages.map(m=>({...m,item:r.item}))).sort((a,b)=>b.at-a.at);content='<p class="muted">Shop repair messages appear here. Push, email and SMS notifications are not connected.</p>'+(messages.length?messages.map(m=>`<article class="card"><strong>${esc(m.item)}</strong><p>${esc(m.text)}</p><small>${new Date(m.at).toLocaleString('en-IN')}</small></article>`).join(''):'<p>No repair messages yet.</p>');}
 if(kind==='Help')content='<h3>Orders & delivery</h3><p>Open My Orders for confirmation, tracking and completed-order receipts.</p><h3>Returns</h3><p>Eligible delivered items show Request return in their order. Check the item’s return window.</p><h3>Repairs</h3><p>Upload a device photo and problem in Repair Centre. Keep your repair ID to check the owner’s price and updates.</p><p>This preview has no connected support phone or live chat.</p>';
 view.innerHTML=`<section class="card profile-panel"><h2>${titles[kind]}</h2>${content}<p><button class="secondary" id="panelBack">Back to profile</button></p></section>`;pageBack(profileView,'Back to profile');document.querySelector('#panelBack').onclick=profileView;if(document.querySelector('#panelOrders'))document.querySelector('#panelOrders').onclick=action(orders);
}

let profileOrderContext=false,collectionReturnTo=null;
function pageBack(goBack,label='Back'){
 const old=view.querySelector('.page-back');if(old)old.remove();const button=document.createElement('button');button.className='page-back secondary';button.setAttribute('aria-label',label);button.title=label;button.innerHTML=icon('back');button.onclick=action(goBack);view.prepend(button);
}
function detailHighlights(p){
 const list=highlightsFor(p);if(!list.length)return '';
 return `<section class="card detail-features"><h3>Key features</h3><ul>${list.map(t=>`<li>${icon('check')}<span>${esc(t)}</span></li>`).join('')}</ul></section>`;
}
function detailExtras(p){
 const rows=[p.warranty&&['Warranty',p.warranty],p.in_the_box&&["What's in the box",p.in_the_box]].filter(Boolean);
 if(!rows.length)return '';
 return `<section class="card detail-extras"><h3>Warranty & box contents</h3><dl class="product-specifications">${rows.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></section>`;
}
function detailAssurance(p){
 const fee=money(DELIVERY_FEE),free=money(FREE_DELIVERY_FROM);
 return `<div class="card detail-delivery"><h3>${icon('truck')} Delivery, payment & returns</h3><ul class="detail-assure">
 <li><strong>Delivery</strong><span>Free on orders of ${free} or more, otherwise ${fee}. The shop confirms your order before packing.</span></li>
 <li><strong>Payment</strong><span>Cash on delivery, or UPI / card / net banking (online payments are a demo here).</span></li>
 <li><strong>Returns</strong><span>${esc(returnLabel(p))}. The policy is saved with your order.</span></li>
 ${p.warranty?`<li><strong>Warranty</strong><span>${esc(p.warranty)}</span></li>`:''}</ul></div>`;
}
function relatedProducts(p){
 const list=state.products.filter(x=>x.active&&x.id!==p.id&&x.category===p.category).slice(0,8);
 if(!list.length)return '';
 return `<section class="detail-related"><h3>More in ${esc(categoryLabels[p.category]||p.category)}</h3><div class="related-row">${list.map(x=>`<button class="related-card" data-related="${x.id}" aria-label="View ${esc(x.name)}"><span class="related-img">${itemVisual(x)}</span><span class="related-name">${esc(x.name)}</span><span class="related-price">${priceTag(x,money)}</span></button>`).join('')}</div></section>`;
}
async function productDetails(id,backTo=shop){
 disposeMap();reloadLocal();const p=state.products.find(p=>p.id===id);if(!p)throw Error('This product is unavailable.');view.classList.remove('searching');selectNav('navShop');
 const reviews=await api('/reviews/'+id),owner=adminPath&&user?.role==='admin',available=p.active&&p.stock>0;
 const specs=p.specifications||{};
 view.innerHTML=`<section class="product-details-page"><div class="product-detail-layout"><div class="product-gallery"><div class="product-main-photo">${itemVisual(p)}</div><p class="muted">${p.sample_listing?'Manufacturer reference image; finish may vary.':'Product image'}</p></div><div class="product-detail-info"><p class="product-brand">${esc(p.brand||categoryLabels[p.category]||'Dev Computer')}</p><h2>${esc(p.name)}</h2><p class="muted">${ratingSummary(id)}</p><p class="price">${priceTag(p,money)}</p>${savings(p)?`<p class="detail-save">You save ${money(savings(p))} on this item</p>`:''}<p class="detail-description">${esc(p.description)}</p><p class="status-pill">${!p.active?'No longer sold':p.stock?p.stock+' available':'Out of stock'}</p><p class="policy-tag ${p.returnable?'return-yes':''}">${returnLabel(p)}</p>${p.sample_listing?'<p class="notice">Sample price and stock for the demo. Confirm the exact model configuration with the shop.</p>':''}<div class="product-purchase-actions">${owner?'<button id="detailEdit">Edit product</button>':`<button id="detailAdd" ${available?'':'disabled'}>${icon('bag')} ${cart[id]?'Add another · '+cart[id]+' in cart':'Add to cart'}</button><button id="detailBuy" class="secondary" ${available?'':'disabled'}>Buy now</button><button id="detailWish" class="secondary" aria-pressed="${savedData().wishlist.includes(id)}">${icon('heart',{filled:savedData().wishlist.includes(id)})} ${savedData().wishlist.includes(id)?'Wishlisted':'Save to wishlist'}</button>`}</div>${detailAssurance(p)}</div></div>${detailHighlights(p)}<section class="card detail-specs"><h3>Specifications</h3><dl class="product-specifications">${Object.entries({Category:categoryLabels[p.category]||p.category,Brand:p.brand||'Not specified',...specs}).map(([k,v])=>`<div><dt>${esc(k==='SuitableFor'?'Best for':k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${!Object.keys(specs).length?'<p class="muted">Further model specifications have not been supplied by the owner.</p>':''}</section>${detailExtras(p)}${relatedProducts(p)}<section class="card"><div class="row"><h3>Ratings & reviews</h3><button id="detailReviews" class="secondary">View all reviews</button></div><p>${ratingSummary(id)}</p>${reviews.slice(0,3).map(r=>`<article class="detail-review"><strong>${esc(r.display_name)}</strong><p>${r.rating}/5 · Verified purchase</p><p>${esc(r.text)}</p>${r.photo?`<img class="review-photo" src="${esc(r.photo)}" alt="Customer review photo">`:''}</article>`).join('')||'<p class="muted">No reviews yet. Customers can review this item after delivery.</p>'}</section></section>`;
 pageBack(backTo,'Back to previous page');window.scrollTo(0,0);
 document.querySelectorAll('[data-related]').forEach(b=>b.onclick=action(()=>productDetails(+b.dataset.related,backTo)));
 document.querySelector('#detailReviews').onclick=action(()=>reviewsView(id,()=>productDetails(id,backTo)));
 if(owner)document.querySelector('#detailEdit').onclick=()=>productForm(p);
 else{
 document.querySelector('#detailAdd').onclick=action(()=>{addItem(id);document.querySelector('#detailAdd').innerHTML=icon('bag')+' Add another · '+cart[id]+' in cart';});
 document.querySelector('#detailBuy').onclick=action(()=>{if(!cart[id])addItem(id);if(!user){login('checkout');return;}checkoutForm();pageBack(()=>productDetails(id,backTo),'Back to product');});
 document.querySelector('#detailWish').onclick=()=>{const added=toggleWish(id),b=document.querySelector('#detailWish');b.innerHTML=icon('heart',{filled:added})+(added?' Wishlisted':' Save to wishlist');b.setAttribute('aria-pressed',String(added));message(added?'Added to your wishlist':'Removed from your wishlist');};
 }
}

function avatarMarkup(key,name='Customer'){
 const themes={lime:['#b6f783','#344f31'],sky:['#9bd8ff','#294a68'],rose:['#f4b8ce','#65364b'],amber:['#ffd38a','#66502d']};
 if(key==='initials'){const initials=name.trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase();return `<span class="avatar-initials">${esc(initials)}</span>`;}
 const [background,hair]=themes[key]||themes.lime;
 return `<svg class="avatar-art" viewBox="0 0 80 80" aria-hidden="true"><circle cx="40" cy="40" r="40" fill="${background}"/><path d="M12 80v-6c0-18 56-18 56 0v6" fill="${hair}"/><path d="M32 52h16v15H32z" fill="#dfaa84"/><ellipse cx="40" cy="35" rx="20" ry="23" fill="#f0c7a3"/><path d="M20 35V24C20 5 61 5 61 27v9l-8-15c-8 10-18 10-28 6l-5 8" fill="${hair}"/><circle cx="32" cy="36" r="2" fill="#243027"/><circle cx="48" cy="36" r="2" fill="#243027"/><path d="M34 46q6 5 12 0" stroke="#784b3f" stroke-width="2" fill="none" stroke-linecap="round"/>${key==='sky'?'<path d="M24 33h13v9H24zm19 0h13v9H43zm-6 3h6" fill="none" stroke="#294a68" stroke-width="2"/>':''}</svg>`;
}
function avatarPicker(){
 if(!user){login('profile');return;}const data=savedData(),name=data.profile?.name||'Customer';selectNav('navProfile');
 const options=[['lime','Lime avatar'],['sky','Sky avatar'],['rose','Rose avatar'],['amber','Amber avatar'],['initials','My initials']];
 view.innerHTML=`<section class="card avatar-picker"><h2>Choose your avatar</h2><p class="muted">Pick a profile picture. It is saved on this browser or app installation.</p><div class="avatar-options">${options.map(([key,label])=>`<button class="avatar-option secondary" data-avatar="${key}" aria-pressed="${(data.avatarKey||'lime')===key}"><span class="avatar-preview">${avatarMarkup(key,name)}</span><span>${label}</span></button>`).join('')}</div></section>`;
 pageBack(profileView,'Back to profile');document.querySelectorAll('[data-avatar]').forEach(b=>b.onclick=action(()=>{reloadLocal();savedData().avatarKey=b.dataset.avatar;save();profileView();message('Profile avatar saved');}));
}
